const HOUSES_F = { ...HOUSES, year: ["มรณะ","ศุภะ","กัมมะ","ลาภะ","พยายะ","ทาสี","ทาสา"] };
const sexOf = o => (!o ? "" : o.sex !== undefined ? o.sex : o.rows && o.rows.sex !== undefined ? o.rows.sex : (o.p && o.p.sex) || "");
const HSX = o => (sexOf(o) === "f" ? HOUSES_F : HOUSES);   // o = ch หรือ ch.rows
const OPPH = o => HSX(o).year[6];                           // เรือนบริวารเพศตรงข้าม (หลัก ๗ ฐาน ๓)
