function s9TrEval(T) {
  const hits = [], rules = [], bySlot = { year: [], month: [], day: [] };
  if (!S9E.tr || !S9E.tr.length) return { hits, rules, bySlot };
  const slots = [];
  if (T && T.Y) slots.push({ k: "year", lab: `ปีจร (อายุย่าง ${TH(T.age)} ปี)`, n: T.Y.n, sum: T.Y.sum, h: T.Y.house });
  if (T && T.M) slots.push({ k: "month", lab: "เดือนจรนี้", n: T.M.n, sum: T.M.sum, h: T.M.house });
  if (T && T.D) slots.push({ k: "day", lab: "วันจรนี้", n: T.D.n, sum: T.D.sum, h: T.D.house });
  S9E.tr.forEach(c => {
    if (c.k === "rule" || c.p == null) { rules.push(c.id); return; }
    const where = [], ks = [];
    slots.forEach(s => {
      if (s.n === c.p && (c.b == null || s.sum === c.b)) {
        where.push(`${s.lab}: เลข ${TH(s.n)} ${P[s.n].n} เรือน${s.h} · ฐานบวก ${TH(s.sum)}`);
        ks.push(s.k);
        bySlot[s.k].push(c.id);
      }
    });
    if (where.length) hits.push({ c, where, ks });
  });
  return { hits, rules, bySlot };
}
