const relText = (a, b) => REL[`${a}|${b}`] || REL[`${b}|${a}`] || "";
// ดาวบนฐานกำลังพิเศษ ๙ ๑๑ ๑๓ ๑๔ ๑๖ ๑๘ (ภาค ๑ หน้า ๖๘–๗๓) · ชนเสีย = คุณข้างต้นถูกตัดทอน
function spbOf(p, sum, bad) {
  const s = SPB[sum]; if (!s) return null;
  return { n: s.n, g: s.g, t: (s.p && s.p[p]) || "", cut: bad ? s.bad : "" };
}

function pairTypes(a, b, badA, badB) {
  const has = p => p.list.some(([x, y]) => (x === a && y === b) || (x === b && y === a));
  const cd = PAIR_COND[pairKey(a, b)];
  if (!cd) return PAIRS.filter(has);
  const bad = n => (n === a && badA) || (n === b && badB);
  return cd.who.some(bad) ? PAIRS.filter(p => p.type === cd.to) : PAIRS.filter(p => p.type !== cd.to && has(p));
}
const pairSc = ty => ty.reduce((x, p) => x + p.sc, 0);
const MID_DBL = "โยงมัชฌิมา แต่ชนเสียสองต่อ มัชฌิมาไม่รับ ปล่อยให้เสียตามนั้น";
const midDbl = c => !!(c && c.mid && c.heavy.length >= 2);   // v7.5.6
