function chartPanes(ch, T) {
  const C = {}, F = o => ({ ...o, h: thaiFrag(paneNoDet(o.h)) });
  ROW3.forEach(k => { for (let c = 0; c < 7; c++) C[cid(k, c)] = F(cellPane(ch, k, c)); });
  ["b8", "b9"].forEach(k => { for (let c = 0; c < 7; c++) C[cid(k, c)] = F(cell89Pane(ch, k, c)); });
  ["b5", "b6", "b7"].forEach(k => { for (let c = 0; c < 7; c++) C[cid(k, c)] = F(cellLowPane(ch, k, c)); });
  for (let c = 0; c < 7; c++) C[cid("sum", c)] = F(cellSumPane(ch, c));
  const M = {};
  if (T) CH_MODES.forEach(([m, key]) => { if (T[key]) M[m] = F(trPane(T[key])); });
  return JSON.stringify({ c: C, m: M }).replace(/</g, "\\u003c");
}
function chartTable(ch, T) {
  // v2.1 ผังตามแบบ yam7 (ภาพ IMG_4643): หัวแถว ๑–๙ · ชื่อเรือนใต้เลข · เส้นแบ่งหลัก ๓|๔|๕ และฐาน · ⭐🔥 ทุกแถว
  const tk = ch.taksa, big = bigOn();
  const roleOf = n => tk[n] || "";
  const icoN = n => TK_ICON[roleOf(n)] || "";
  const icoS = v => Object.keys(SUM_OWN).filter(n => SUM_OWN[n].includes(v)).map(n => icoN(+n)).join("");
  const G = big ? { g: 64, s: 58, n: 46, cg: 5 } : { g: 58, s: 54, n: 42, cg: 6 }, GAP = 6, SEP = 16;
  const ORD = [["day", "g"], ["month", "g"], ["year", "g"], ["sum", "s"], ["b5", "n"], ["b6", "n"], ["b7", "n"], ["b8", "g"], ["b9", "g"]];
  const top = {}; let y = 0;
  ORD.forEach(([k, t], i) => { if (i) y += ["sum", "b5", "b8"].includes(k) ? SEP : GAP; top[k] = y; y += G[t]; });
  const cg = G.cg + "px", cx = n => `calc(${n} * (100% - 6 * ${cg}) / 7 + ${n} * ${cg} - ${G.cg / 2}px)`;
  const midS = k => top[k] - SEP / 2, midG = k => top[k] - GAP / 2;
  const lines = [3, 4].map(n => `<i class="cl v" style="left:${cx(n)};top:-3px;height:${midS("sum") + 3}px"></i>`).join("")
    + ["month", "year"].map(k => `<i class="cl h" style="top:${midG(k)}px;left:${cx(2)};width:calc(3 * (100% - 6 * ${cg}) / 7 + 3 * ${cg})"></i>`).join("")
    + ["sum", "b5", "b8"].map(k => `<i class="cl h" style="top:${midS(k)}px;left:0;width:100%"></i>`).join("");
  const cellOf = (v, i, k) => {
    const sum = k === "sum", hz = CH_HZ.includes(k) ? houseAt(k, i, ch) : sum ? sumShort(v) : "", lo = /^b[5-7]$/.test(k), ic = sum ? icoS(v) : icoN(v);
    return `<div class="cell${sum ? ` sm sg-${SUMGRP(v)}` : ` p${v}`}${lo ? " lo" : ""}" id="${cid(k, i)}"><b>${TH(v)}</b>${hz ? `<span class="chn${chnCls(hz)}">${esc(hz)}</span>` : ""}${ic ? `<i class="tki">${ic}</i>` : ""}</div>`;
  };
  const rows = ORD.map(([k, t]) => `<div class="crow" style="top:${top[k]}px;height:${G[t]}px">${chRowVals(ch, k).map((v, i) => cellOf(v, i, k)).join("")}</div>`).join("");
  const rn = `<div class="rn" style="height:${y}px">${ORD.map(([k, t], i) => `<span style="top:${top[k]}px;height:${G[t]}px">${TH(i + 1)}</span>`).join("")}</div>`;
  const grid = `<div class="t7">${rn}<div class="grid" id="g" style="height:${y}px">${lines}${rows}</div></div>`;
  const modes = T ? `<div class="mode" id="mode"><a class="on" data-m="natal">พื้นดวง</a>${CH_MODES.filter(([, key]) => T[key]).map(([m, , lab]) => `<a data-m="${m}">${lab}</a>`).join("")}</div>` : "";
  return `<div class="chb">${modes}${grid}</div>
<div class="leg2"><span><i style="background:color-mix(in srgb,var(--p5) 20%,var(--card));box-shadow:inset 0 0 0 2px var(--p5)"></i>เลขที่แตะ · เลขเดียวกัน</span><span><i style="box-shadow:inset 0 0 0 2px var(--p2);border-radius:50%"></i>เลขจับคู่ ทุกฐานรวม ๕–๗</span><span><i style="box-shadow:inset 0 0 0 2px var(--acc)"></i>ฐานรองรับ</span><span>สีตามดาว (ภาค ๒ หน้า ๓๔๐) · ⭐ ศรี · 🔥 กาลกิณี (ฐาน ๔ ใช้ฐานกำลังของดาว)</span></div>
<div class="pane" id="pane" style="display:none"></div>
<div class="lg"><b>แตะช่องไหนก็ได้</b> เพื่ออ่านใต้ผัง (แตะซ้ำเพื่อปิด) · หัวแถว ๑–๙ คือฐาน ๑–๙ (๑ วัน ๒ เดือน ๓ ปี ๔ ฐานรวม) · แตะเลขฐาน ๑–๓ จะจับคู่กับฐาน ๕–๗ หลักเดียวกันให้เห็นเลขจับคู่ (ได้เลขตัวเดียวกันเรียกว่า ย้ำ) · ${T ? "ปุ่มปีจร เดือนจร วันจร ยามจร แสดงจร ณ ตอนนี้บนผังเดียวกัน · " : ""}ทักษาพื้นชะตาจากวันเกิด (ภาค ๒ หน้า ๓๑๐–๓๒๔) · เลขฐาน ๔ ลงสีตามกลุ่มฐานรวม <span style="color:var(--good)">ดี</span> <span style="color:var(--mid)">ปานกลาง</span> <span style="color:var(--bad)">ไม่ดี</span> (ภาค ๑ หน้า ๔๕)</div>`;
}
// v2.1.1 ชื่อภพยาวย่อขนาดตัวอักษรแทนการตัด "…" — นับเฉพาะพยัญชนะ/สระที่กินที่ (ไม่นับสระบน-ล่าง วรรณยุกต์)
