// ---- การ์ดรอบ ๑ ----
// คะแนนเป็นกำลังของเลขที่ตั้งเรือน ไม่ใช่คำว่าดีสำหรับเจ้าชะตา: เรือนเสียที่เลขแรง = เรื่องร้ายยิ่งสำแดง (ภาค ๒ หน้า ๑๘๒ ๑๙๕)
const BADV = s => (s >= 88 ? ["ร้ายชัด", "b"] : s >= 75 ? ["ร้ายค่อนชัด", "b"] : s >= 60 ? ["ร้ายพอประมาณ", "b"] : s >= 45 ? ["ร้ายเบาลง", ""] : ["แทบไม่สำแดง", "g"]);
function scPill(sc, h, k) {
  const bad = h !== undefined && houseTone(h, k) < 0;
  const [w, c] = bad ? BADV(sc.score) : [sc.word, SC_CLS[sc.lv]];
  return `<span class="pill ${c}">${mkS(w)}${TH(sc.score)} ${esc(w)}</span>`;
}
function overviewCard(ch, rd) {
  const sf = rd.self;
  // v2.0 แถวชื่อซ้าย ป้ายขวา — ป้ายคะแนนไม่ตกบรรทัดกลางประโยคอีก
  const li = (x, warn) => `<div class="lr"><div class="lx"><b>${esc(x.h)}</b>${x.also && x.also.length ? ` <span class="pk">+ ${esc(x.also.join(" "))}</span>` : ""}<div class="lm2">${esc(shortMean(x.h, x.key) || x.mean)}${warn ? ` — ${esc(rd.warnWhy(x))}` : ""}</div></div>${scPill(x.sc, x.h, x.key)}</div>`;
  const tile = (lab, sc, h, k) => { const [w, c] = [sc.word, SC_CLS[sc.lv]]; return `<div class="stt"><small>${lab}</small><b>${TH(sc.score)}</b><em class="${c}">${mkW(w)}</em></div>`; };
  return `<div class="card"><h2>ภาพรวมพื้นดวง <span>คะแนนตัวเจ้าชะตา เต็ม ๒๐๐ (ภาค ๒ หน้า ๑๘๒–๑๘๓)</span></h2>
<div class="tot"><b>${TH(sf.total)}</b><i>/ ๒๐๐ · ${mkW(sf.word)}</i></div>
<div class="st2">${tile("อัตตะ · วันเกิด", sf.atta.sc, "อัตตะ", "day")}${tile("ตนุ · เดือนเกิด", sf.tanu.sc, "ตนุ", "month")}</div>
<div class="hr"><div class="hn">เด่น</div>${rd.top.length ? rd.top.map(x => li(x, false)).join("") : `<div class="hl">ไม่มีเรือนที่ถึงระดับดีในฐาน ๑–๓</div>`}</div>
<div class="hr"><div class="hn">ระวัง</div>${rd.warn.length ? rd.warn.map(x => li(x, true)).join("") : `<div class="hl">ไม่มีเรือนที่ต้องระวังเป็นพิเศษ</div>`}</div>
<details><summary>คะแนนนี้คิดอย่างไร</summary><div class="foot">
คะแนนเป็นของ<b>เลขที่ตั้งเรือน</b> ไม่ใช่ของชื่อเรือน ตามวิธีในตำรา ภาค ๒ หน้า ๑๘๒: ดูเลข → ตามเลขเดียวกันไปทุกฐาน → ดูฐานรองรับ → ดูการชนเสีย<br>
ตั้งต้นจากกลุ่มฐานรองรับ (ดี ๑๐๐ · ปานกลาง ๗๘ · ฐานบาปเคราะห์อ่อน ๔ ๘ ๑๒ = ๗๒ · ฐานบาปเคราะห์ ๓ ๗ ๑๐ ๒๐ = ๖๒) แล้วปรับด้วย เลขศุภ/บาปเคราะห์บนฐานเสีย ±๔ · ชนเสีย −๒๐ และ −๑๐ ต่อเรือนถัดไป (ฐานดีช่วยเหลือ ๒๐% จากหนักเป็นเบา หน้า ๑๙๕) · ชนภพเสียน้อย −๔ · มหาอุปถัมภ์ +๘ · ดาวกับเจ้าของฐานเป็นพวกกัน +๖ เป็นศัตรู −๘ (หน้า ๑๙๓) · ฐาน ๑๒ ราหู −๒ ถึง −๕ · มัชฌิมาทอนเข้าหากลาง ๓๐% · ฐาน ๘ ๙ เรือนดีหนุน +๒ ถึง +๔ เมื่อไม่ชนเสีย<br>
สอบเทียบกับตัวเลขที่ตำราให้: ตัวอย่าง ๑ อัตตะ ๕๐–๖๐ · ตนุ เต็มร้อย · รวม ๑๔๐–๑๖๐ (หน้า ๑๘๒–๑๘๓) · ตัวอย่าง ๒ อัตตะ ๗๐ ตนุ ๗๐ (หน้า ๑๘๗–๑๘๘) — แอปได้ ๕๓ / ๙๖ / ๑๔๙ และ ๗๐ / ๖๐<br>
ระดับคำตัดสิน: ดี ≥ ๘๘ · ค่อนดี ๗๕–๘๗ · กลาง ๖๐–๗๔ · ค่อนร้าย ๔๕–๕๙ · ร้าย &lt; ๔๕ · "ระวัง" รวมสองแบบคือเรือนเสียที่เลขหนักแน่น และเรือนดีที่เลขอ่อน
</div></details></div>`;
}
// v3.9.18 คำอ่านคู่เรือนที่ข้อความตรงกัน (เช่น ทาสีกับทาสาฐาน ๘ หรืออัตตะกับอัตตะฐาน ๙) แสดงบรรทัดเดียว
function relLines(rel) {
  const G = [];
  rel.forEach(r => { const nm = `${r.h}${r.k && is89(r.k) ? `(${B89TH[r.k]})` : ""}`, g = G.find(x => x.t === r.t);
    if (g) { if (!g.h.includes(nm)) g.h.push(nm); } else G.push({ t: r.t, h: [nm] }); });
  return G.map(g => `${esc(g.h.join(" · "))}: ${esc(g.t)}`).join("<br>");
}
function houseBlock(x, first, tag) {
  const rel = x.rel.length ? `<div class="hl">${relLines(x.rel)}</div>` : "";
  return `<div class="hr${first ? " first" : ""}"><div class="hn2"><span class="nm">${esc(x.h)}${tag ? ` <small>${esc(tag)}</small>` : ""} ${TH(x.n)} ${esc(P[x.n].n)}</span>${scPill(x.sc, x.h, x.key)}</div><div class="hn"><span class="w">${esc(x.mean || "")}</span></div>
<div class="hl">${x.lines.map(esc).join("<br>")}</div>${rel}</div>`;
}
// v3.9.18 เลขเดียวกัน → ฐานรองรับ คำดาวบนฐาน และคำฐานเป็นชุดเดียวกัน (ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปี)
function selfEcho(sf, x, tag) {
  const m = [[sf.atta, "อัตตะ แถววัน"], [sf.tanu, "ตนุ แถวเดือน"]].find(([y]) => y && y.n === x.n);
  if (!m) return houseBlock(x, false, tag);
  return `<div class="hr"><div class="hn2"><span class="nm">${esc(x.h)} <small>${esc(tag)}</small> ${TH(x.n)} ${esc(P[x.n].n)}</span>${scPill(x.sc, x.h, x.key)}</div><div class="hn"><span class="w">${esc(x.mean || "")}</span></div>
<div class="hl">เลข ${TH(x.n)} ตัวเดียวกับ${esc(m[1])} · ฐานรองรับ คำดาวบนฐาน และคำฐาน เหมือนด้านบน (ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปี)</div></div>`;
}
function selfCard(ch, rd) {
  const sf = rd.self, pk = pakRead(ch);
  const isBap = n => n === 1 || n === 3 || n === 7;
  const nGood = pk.filter(p => !isBap(p.n)).length, nBad = pk.length - nGood;
  const pakLead = isBap(pk[0].n) ? "ปากเป็นบาปเคราะห์ (ให้น้ำหนักทางเสีย/ควรระวังก่อน)" : "ปากเป็นสมปเคราะห์ (ให้คุณก่อน)";
  const pakBal = nGood === 3 ? "สมปเคราะห์ครบทั้ง ๓ ฐาน · ทายเด่นไปทางดี"
    : nGood === 2 ? "สมปเคราะห์ ๒ บาปเคราะห์ ๑ (ดี ๒ เสีย ๑) · ทายโน้มไปทางดี"
    : nBad === 2 ? "บาปเคราะห์ ๒ สมปเคราะห์ ๑ (ดี–เสียปะปนกัน) · ทายปานกลางค่อนไปทางต้องระวัง"
    : "บาปเคราะห์ครบทั้ง ๓ ฐาน · ควรระวังอารมณ์ คำพูด และความไม่นิ่งเป็นพิเศษ";
  const pakSumBox = `<div class="kv sub" style="font-size:12.5px;margin-bottom:6px">⚖️ <b>น้ำหนักรวม ปาก–ใจ–ที่นั่ง:</b> ${esc(pakBal)} · ${esc(pakLead)}</div>`;
  const pkLine = p => {
    const grpTag = isBap(p.n) ? `<span class="b" style="font-size:11.5px">บาปเคราะห์</span>` : `<span class="g" style="font-size:11.5px">สมปเคราะห์</span>`;
    const s8 = s8Pak(p.keyT, p.n);
    const s8Fold = s8 ? `<details class="s9" style="margin-top:4px"><summary>เทียบถ้อยคำเดิม ตำรารองเล่ม ๘</summary>${s8}</details>` : "";
    return `<div class="hr"><div class="hn2"><span class="nm">${esc(p.lab)} = ${esc(p.h)} ${TH(p.n)} ${esc(P[p.n].n)}</span> ${grpTag} ${scPill(p.sc, p.h, p.lab === "ที่นั่ง" ? "year" : p.lab === "ใจ" ? "month" : "day")}</div><div class="hn"><span class="w">${esc(p.what)}</span></div>
<div class="hl">${esc(p.t)}</div>${s8Fold}${p.rel.length ? `<div class="hl">${relLines(p.rel)}</div>` : ""}</div>`;
  };
  return `<div class="card"><h2>ตัวเจ้าชะตา <span>อัตตะ ตนุ อาตมา · ปาก ใจ ที่นั่ง</span></h2>
${houseBlock(sf.atta, true)}${houseBlock(sf.tanu)}
${selfSexH(ch)}
${selfEcho(sf, sf.atma, "ฐาน ๘")}${selfEcho(sf, sf.atta9, "ฐาน ๙")}
<details class="grp"><summary>ปาก ใจ ที่นั่ง <span class="sm2">${pk.map(p => `${esc(p.lab)} ${TH(p.n)}`).join(" · ")}</span></summary>${pakSumBox}${pk.map(pkLine).join("")}</details>
<details><summary>ที่มา</summary><div class="foot">
อัตตะ (เลขวันเกิด) และตนุ (เลขเดือนเกิด) คือตัวเจ้าชะตาทั้งคู่ · อาตมา (ฐาน ๘) และอัตตะ (ฐาน ๙) เป็นเรือนประกอบ (ภาค ๑ หน้า ๑๒ · ภาค ๒ หน้า ๑๘๒–๑๘๓)<br>
ปาก = ปิตา · ใจ = พันธุ · ที่นั่ง = ลาภะ — ใช้ชุดหลักเกณฑ์การพยากรณ์รวมที่สังเคราะห์จากหลายตำรา (ตัดเรื่องความชอบในการกิน) · แบ่งบาปเคราะห์ (๑, ๓, ๗) และสมปเคราะห์ (๒, ๔, ๕, ๖) ชั่งน้ำหนักร่วมกัน โดยดูปากเป็นตัวตั้งต้น · พร้อมพับถ้อยคำเดิมตำรารองเล่ม ๘ (KB S8-PJT-001–021) ไว้เทียบด้านล่าง (ไม่คิดคะแนน)
</div></details></div>`;
}
function housesCard(ch, rd) {
  const grp = ([k, lab]) => `<details><summary>${esc(lab)} (๗ ภพ)</summary>${rd[k].map((x, i) => houseBlock(x, i === 0)).join("")}</details>`;
  return `<div class="card"><h2>คำอ่านรายเรือน ๓๕ ภพ <span>ฐานรองรับแบบแถวปี</span></h2>
${NAT_ROWS.map(grp).join("")}
<div class="foot" style="margin-top:9px">ลำดับการอ่านตามตำรา ภาค ๒ หน้า ๑๘๒–๑๙๖ · ฐาน ๘ ๙ ใช้ฐานรองรับของเลขตัวเดียวกันในแถวปีเช่นเดียวกัน</div></div>`;
}

