// ---- มหาทักษา ----
const mtDur = (m, s) => MT_PWR[m] * MT_PWR[s] * 80;   // ชั่วโมง (กำลัง × กำลัง × ๘๐ = กำลัง × กำลัง ÷ ๑๐๘ ปี พอดี ไม่มีเศษทศนิยม)
function mtRows(lord) {   // ๖๔ ช่วง = ดาวเสวยอายุ ๘ ดวง × ดาวแทรก ๘ ดวง เริ่มที่ดาวประจำวันเกิด
  const s0 = TAKSA_ORDER.indexOf(lord), out = [];
  let acc = 0;
  for (let i = 0; i < 8; i++) {
    const m = TAKSA_ORDER[(s0 + i) % 8], mi = TAKSA_ORDER.indexOf(m), mFrom = acc, mTo = acc + MT_PWR[m] * MT_HRY;
    for (let j = 0; j < 8; j++) {
      const sub = TAKSA_ORDER[(mi + j) % 8], dur = mtDur(m, sub);
      out.push({ i, j, m, sub, dur, from: acc, to: acc + dur, mFrom, mTo, ev: MT_EV[m + "/" + sub] || "" });
      acc += dur;
    }
  }
  return out;
}
const mtYMD = h => { const t = Math.max(0, Math.floor(h)); return { y: Math.floor(t / MT_HRY), m: Math.floor(t % MT_HRY / 720), d: Math.floor(t % 720 / 24), h: t % 24 }; };
function mtSpan(h, withHour) {   // ความยาวช่วงเป็นคำอ่าน
  const t = mtYMD(h), p = [];
  if (t.y) p.push(TH(t.y) + " ปี");
  if (t.m) p.push(TH(t.m) + " เดือน");
  if (t.d) p.push(TH(t.d) + " วัน");
  if (withHour && t.h) p.push(TH(t.h) + " ชั่วโมง");
  return p.length ? p.join(" ") : "ไม่ถึงหนึ่งวัน";
}
const mtAgeTxt = h => { const t = mtYMD(h); return TH(t.y) + " ปี " + TH(t.m) + " เดือน " + TH(t.d) + " วัน"; };
function ageExactY(born, now) {   // อายุจริงเป็นปีกับเศษของปี (ใช้วันเกิดเป็นหมุด)
  let y = now.getFullYear() - born.getFullYear();
  const a = new Date(born.getTime()); a.setFullYear(born.getFullYear() + y);
  if (a.getTime() > now.getTime()) { y--; a.setFullYear(a.getFullYear() - 1); }
  const n2 = new Date(a.getTime()); n2.setFullYear(a.getFullYear() + 1);
  return y + (now.getTime() - a.getTime()) / (n2.getTime() - a.getTime());
}
function dateAtAge(born, years) {   // ย้อนกลับจากอายุเป็นวันที่จริง
  const y = Math.floor(years), a = new Date(born.getTime()); a.setFullYear(born.getFullYear() + y);
  const n2 = new Date(a.getTime()); n2.setFullYear(a.getFullYear() + 1);
  return new Date(a.getTime() + (years - y) * (n2.getTime() - a.getTime()));
}
function mtAt(ch, nowIn) {
  const now = nowIn || appNow(), L = mtRows(ch.taksaLord);
  const ageY = ageExactY(ch.born, now), cyc = Math.floor(ageY / 108);
  const hrs = Math.round((ageY - cyc * 108) * MT_HRY);
  const cur = L.find(r => hrs >= r.from && hrs < r.to) || L[L.length - 1];
  return { L, now, ageY, cyc, hrs, cur, nx: L[L.indexOf(cur) + 1] || L[0], left: Math.max(0, cur.to - hrs),
           mains: L.filter(r => r.j === 0), subs: L.filter(r => r.i === cur.i) };
}
// รอบ 87 ข้อตัดสิน 113: อ่านคำทำนายมหาทักษาแยกเรื่อง · ป้ายดี/ระวังจากถ้อยคำของคู่นั้น (ไม่ใช่จากคู่ดาว)
const MT_TOP = { ง: ["💰", "เงินทอง ทรัพย์สิน"], ค: ["💞", "คู่ครอง ลูก ครอบครัว"], ส: ["🩺", "สุขภาพ"], ด: ["⚖️", "คดีความ ศัตรู คำใส่ความ"],
  บ: ["🏠", "บ้าน ที่อยู่ การเดินทาง"], ญ: ["👔", "ผู้ใหญ่ เจ้านาย"], ม: ["🤝", "บริวาร มิตร ญาติ"], "": ["•", "ทั่วไป"] };
const MT_TOPO = ["ง", "ค", "ส", "ด", "บ", "ญ", "ม", ""];
const mtTrim = t => String(t).replace(/^(และ|แต่|แล้ว)\s*/, "");   // รอบ 97 ข้อ 142-๕: เฉพาะตอนแสดงแยกตามเรื่อง
const MT_PL = { g: ["▲", "ดี", "g"], b: ["▼", "ระวัง", "b"], m: ["◐", "ดีปนระวัง", ""] };
function mtPol(k) { const v = MT_READ[k] || [], p = v.some(x => x[1] === "+"), n = v.some(x => x[1] === "-"); return p && n ? "m" : p ? "g" : "b"; }
const mtPill = k => { const x = MT_PL[mtPol(k)]; return `<span class="pill ${x[2]}"><span class="lvm">${x[0]}</span> ${x[1]}</span>`; };
function mtByTop(k) {   // { รหัสเรื่อง: [[วลี, ขั้ว]] } เรียงตาม MT_TOPO · วลีที่มีหลายเรื่องขึ้นทุกเรื่อง
  const o = {}; (MT_READ[k] || []).forEach(([t, p, c]) => (c ? [...c] : [""]).forEach(x => (o[x] = o[x] || []).push([t, p])));
  return MT_TOPO.filter(x => o[x]).map(x => ({ c: x, L: o[x] }));
}
function mtPair(m, sub) {   // คู่ดาวตามตาราง PAIRS (น.๓๐๑ ใช้ คู่มิตร คู่ธาตุ คู่สมพล ให้คุณ · คู่ศัตรู ให้โทษหนัก)
  if (m === sub) return "ดาวเดียวกัน";
  const hit = PAIRS.filter(g => g.type !== "คู่ศัตรูน้อย" && g.list.some(([x, y]) => (x === m && y === sub) || (x === sub && y === m))).map(g => g.type);
  return hit.length ? hit.join("และ") : "";
}
function mtCard(ch, nowIn) {
  if (ch.synth || !ch.born) return "";
  const A = mtAt(ch, nowIn), c = A.cur, ci = A.L.indexOf(c), K = r => r.m + "/" + r.sub;
  const dOf = h => dateTH(dateAtAge(ch.born, A.cyc * 108 + h / MT_HRY));
  const dAt = (r, cy) => dateTH(dateAtAge(ch.born, cy * 108 + r.from / MT_HRY));
  const row = r => `<tr${r === c ? ' style="font-weight:600"' : ""}><td>${r === c ? "➤ " : ""}${esc(P[r.sub].n)}</td><td>${mtSpan(r.dur, true)}</td><td>${mtAgeTxt(r.from)}</td><td>${mtPill(K(r))} ${esc(r.ev)}</td></tr>`;
  const mrow = r => `<tr${r.i === c.i ? ' style="font-weight:600"' : ""}><td>${r.i === c.i ? "➤ " : ""}${esc(P[r.m].n)}</td><td>${TH(MT_PWR[r.m])} ปี</td><td>${mtAgeTxt(r.mFrom)} – ${mtAgeTxt(r.mTo)}</td></tr>`;
  const topRows = k => mtByTop(k).map(({ c: x, L }) => `<div class="mtr"><span class="mti">${MT_TOP[x][0]}</span><span><b>${esc(MT_TOP[x][1])}</b> ${L.map(([t, p]) => `<span class="${p === "+" ? "g" : "b"}">${p === "+" ? "▲" : "▼"}</span> ${esc(mtTrim(t))}`).join(" · ")}</span></div>`).join("");
  const pr = mtPair(c.m, c.sub), pol = mtPol(K(c));
  const prTxt = pr === "ดาวเดียวกัน" ? `ช่วงนี้ดาวแทรกเป็นดาวเดียวกับดาวเสวย (${esc(P[c.m].n)}เข้าแทรกตัวเอง)`
    : pr ? `${esc(P[c.m].n)}กับ${esc(P[c.sub].n)}เป็น${esc(pr)} · หลักในตำราหน้า ๓๐๑ ว่า${/ศัตรู/.test(pr) ? "คู่ศัตรูให้โทษหนัก" : "คู่มิตร คู่ธาตุ คู่สมพลให้คุณ"}${(/ศัตรู/.test(pr) && pol === "g") || (!/ศัตรู/.test(pr) && pol === "b") ? " แต่คำทำนายของคู่นี้ทายไปอีกทาง ป้ายจึงยึดคำทำนาย" : ""}`
    : `${esc(P[c.m].n)}กับ${esc(P[c.sub].n)}ไม่อยู่ในคู่มิตร คู่ธาตุ คู่สมพล หรือคู่ศัตรู`;
  // ช่วงข้างหน้า ๘ ช่วง (ข้ามรอบ ๑๐๘ ปีได้) · ช่วงดี / ระวัง ถัดไปค้นไม่เกิน ๖๔ ช่วง
  const ahead = []; for (let i = 1; i <= 64; i++) { const j = ci + i; ahead.push({ r: A.L[j % 64], cy: A.cyc + Math.floor(j / 64) }); }
  const nG = ahead.find(x => mtPol(K(x.r)) === "g"), nB = ahead.find(x => mtPol(K(x.r)) === "b");
  const nx = x => `${esc(P[x.r.m].n)}เสวย ${esc(P[x.r.sub].n)}แทรก · เริ่ม ${esc(dAt(x.r, x.cy))}`;
  const strip = ahead.slice(0, 8).map(x => `<div class="mtw"><div class="mt0">${esc(dAt(x.r, x.cy))}</div><div>${esc(P[x.r.m].n)} › <b>${esc(P[x.r.sub].n)}</b><small>${mtByTop(K(x.r)).map(t => MT_TOP[t.c][0]).join(" ")} ${esc(x.r.ev)}</small></div><div>${mtPill(K(x.r))}</div></div>`).join("");
  return `<div class="card"><h2>มหาทักษา ดาวเสวยอายุ <span>ตำรา ภาค ๒ หน้า ๓๐๑–๓๐๙</span></h2>
<div class="mte"${hlA("mtM", hlPl(ch, c.m, c.sub, "มหาทักษา · ดาวเสวย " + P[c.m].n + " แทรก " + P[c.sub].n))}><div class="mth">อ่านง่าย ✎ ช่วงนี้ <b>${esc(P[c.m].n)}เสวย ${esc(P[c.sub].n)}แทรก</b> ${mtPill(K(c))}</div>
<div class="kv sub" style="margin:2px 0 6px">${esc(dOf(c.from))} ถึง ${esc(dOf(c.to))} · เหลืออีก ${mtSpan(A.left)}</div>${topRows(K(c))}
<div class="kv sub" style="font-size:12px;margin-top:6px">${prTxt} · ป้ายและการแยกเรื่องแอปจัดจากถ้อยคำทำนายของตำรา ไม่ใช่ถ้อยคำในเล่ม</div></div>
<div class="kv">• <b>ช่วงดีถัดไป</b> ${nG ? nx(nG) : "ไม่พบใน ๖๔ ช่วงข้างหน้า"}<br>• <b>ช่วงระวังถัดไป</b> ${nB ? nx(nB) : "ไม่พบใน ๖๔ ช่วงข้างหน้า"}</div>
<div class="kv"${hlA("mtN", hlPl(ch, A.nx.m, A.nx.sub, "มหาทักษา ช่วงถัดไป · เสวย " + P[A.nx.m].n + " แทรก " + P[A.nx.sub].n))}><b>ช่วงข้างหน้า ๘ ช่วง</b></div>
<div class="mtn">${strip}</div>
<div class="kv"${hlA("mtS", hlPl(ch, c.sub, null, "มหาทักษา · ดาวแทรก " + P[c.sub].n))}>• <b>ดาวเสวยอายุ</b> ${esc(P[c.m].n)} (กำลัง ${TH(MT_PWR[c.m])} ปี) ช่วงอายุ ${mtAgeTxt(c.mFrom)} ถึง ${mtAgeTxt(c.mTo)}<br>
<span style="color:var(--tx2)">${esc(P[c.m].tay)}</span></div>
<div class="kv" style="color:var(--tx3);font-size:11.5px">อายุที่ใช้คืออายุจริง ${TH(Math.floor(A.ageY))} ปีเศษ (ไม่ใช่อายุย่าง) นับจากวันเกิดตามที่ตำราวางตารางไว้${A.cyc ? ` · ครบ ๑๐๘ ปีแล้ว ${TH(A.cyc)} รอบ จึงวนนับใหม่` : ""}</div>
<details><summary>ดาวแทรกทั้ง ๘ ช่วงในรอบ${esc(P[c.m].n)}</summary><div class="foot">
<div class="tbw"><table class="tb"><tr><th>ดาวแทรก</th><th>ยาว</th><th>เริ่มเมื่ออายุ</th><th>ตำราว่า</th></tr>${A.subs.map(row).join("")}</table></div>
</div></details>
<details><summary>ลำดับดาวเสวยอายุทั้งชีวิต ๑๐๘ ปี</summary><div class="foot">
<div class="tbw"><table class="tb"><tr><th>ดาวเสวยอายุ</th><th>กำลัง</th><th>ช่วงอายุ</th></tr>${A.mains.map(mrow).join("")}</table></div>
</div></details>
<details><summary>วิธีคำนวณและที่มา</summary><div class="foot">
ลำดับดาวเวียนขวาตามผังทักษา ๑ → ๒ → ๓ → ๔ → ๗ → ๕ → ๘ → ๖ แล้ววนกลับ เริ่มที่ดาวประจำวันเกิด (หน้า ๓๐๑)<br>
ระยะดาวแทรก = กำลังดาวเสวย × กำลังดาวแทรก ÷ ๑๐๘ ปี แล้วแปลงเศษเป็นเดือน วัน ชั่วโมง (๑ ปี = ๑๒ เดือน · ๑ เดือน = ๓๐ วัน) หน้า ๓๐๒<br>
แอปคิดเป็นชั่วโมงจำนวนเต็ม (กำลัง × กำลัง × ๘๐ ชั่วโมง) จึงไม่มีเศษปัดทิ้ง และรวมทั้ง ๖๔ ช่วงได้ ๑๐๘ ปีพอดีทุกวันเกิด<br>
คำทำนาย ๖๔ คู่ยกจากตารางในตำรา ตรวจแล้วว่าตารางทั้ง ๗ วันใช้ข้อความชุดเดียวกัน ต่างกันเพียงวรรคตอน<br>
ป้าย ▲ ดี ▼ ระวัง ◐ ดีปนระวัง: แอปแบ่งคำทำนายของแต่ละคู่เป็นวลี (ถ้อยคำเดิม) แล้วดูว่าวลีทายไปทางได้หรือทางเสีย · ทุกวลีทางได้ = ดี · ทุกวลีทางเสีย = ระวัง · มีทั้งสอง = ดีปนระวัง ✎<br>
หลักคู่ดาวในหน้า ๓๐๑ (คู่มิตร คู่ธาตุ คู่สมพลให้คุณ คู่ศัตรูให้โทษหนัก) ขัดกับคำทำนายในตาราง ๑๐ คู่ เช่น อาทิตย์เสวยเสาร์แทรกเป็นคู่ธาตุแต่ทายว่ามีคดีความ แอปจึงแสดงคู่ดาวประกอบ และยึดคำทำนายเป็นป้าย<br>
ตำราไม่ได้บอกว่าให้ใช้ปีปฏิทินจริงหรือปีโหร ๓๖๐ วัน แอปเลือกนับอายุจากวันเกิดจริงแล้วแตกเศษของปีเป็นเดือนวันตามอัตราของตำรา<br>
${esc(TK_SRC)}
</div></details></div>`;
}

// v3.9.11 ตารางทักษาของวันเกิด: วงเวียนขวา ๑→๒→๓→๔→๗→๕→๘→๖ ตรงกับ TAKSA_ORDER · กลาง = เกตุ (ระบบเลข ๗ ตัวไม่ลักเข้าตากลาง)
const TK_GRID = [1, 2, 3, 6, 9, 4, 8, 5, 7];
function taksaGridCard(ch, nowIn) {
  if (!ch.born || !ch.taksa) return "";
  const now = nowIn || appNow(), lord = ch.taksaLord, map = ch.taksa;
  let cur = null; try { cur = tkTransit(ch, ageYang(ch.born, now)); } catch (e) { cur = null; }
  const stars = TAKSA_ORDER.map((_, i) => TAKSA_ORDER[(TAKSA_ORDER.indexOf(lord) + i) % 8]);
  const sDej = stars[2], sSri = stars[3], sKal = stars[7];
  const keyBar = `<div class="tk-keybar">
<div class="tk-k g"><div class="tk-kl">⭐ ศรี (โชค·เมตตา)</div><div class="tk-kv">ดาว${esc(P[sSri].n)} (${TH(sSri)})</div></div>
<div class="tk-k m"><div class="tk-kl">🔥 เดช (อำนาจ·บารมี)</div><div class="tk-kv">ดาว${esc(P[sDej].n)} (${TH(sDej)})</div></div>
<div class="tk-k b"><div class="tk-kl">⚠ กาลกิณี (ระวัง)</div><div class="tk-kv">ดาว${esc(P[sKal].n)} (${TH(sKal)})</div></div>
<div class="tk-k n"><div class="tk-kl">📍 ปีนี้${cur ? ` (อายุ ${TH(cur.age)})` : ""}</div><div class="tk-kv">${cur ? `ภูมิ${esc(cur.role)} · ${esc(P[cur.star].n)} (${TH(cur.star)})` : "—"}</div></div>
</div>`;
  const cell = n => {
    if (n === 9) return `<div class="tkc tk0"><b>${TH(9)}</b><small>เกตุ · ตากลาง</small><i>ไม่ลักเข้าตากลาง</i></div>`;
    const st = n, role = map[st] || "", g = TAKSA_GRP[role];
    const now1 = cur && cur.star === st;
    const isDej = role === "เดช";
    return `<div class="tkc ${g > 0 ? "tkg" : g < 0 ? "tkb" : ""}${isDej ? " tkd" : ""}${now1 ? " tkn" : ""}">${TK_ICON[role] ? `<span class="tkx">${TK_ICON[role]}</span>` : ""}<b>${TH(st)}</b><small>${esc(P[st].n)}</small><i>${esc(role)}</i>${now1 ? `<span class="tk-nowb">ปีนี้</span>` : ""}</div>`;
  };
  const night = lord === 8 ? `<div class="kv" style="color:var(--tx3);font-size:11.5px">เกิดวันพุธกลางคืน ตำราให้ราหู (๘) เป็นบริวาร</div>` : "";
  return `<div class="card"><h2>ตารางทักษา ๘ ภูมิ <span>คนเกิดวัน${esc(DAYS[ch.dayIdx])} · ตำรา ภาค ๒ หน้า ๓๑๐–๓๑๑</span></h2>
${keyBar}
<div class="tkgrid">${TK_GRID.map(cell).join("")}</div>${night}
<div class="kv" style="color:var(--tx3);font-size:11.5px">เขียว = ฝ่ายดี · แดง = ฝ่ายร้าย · ป้ายทอง = ทักษาจรปีนี้${cur ? ` (อายุย่าง ${TH(cur.age)} ภูมิ${esc(cur.role)})` : ""} · รายละเอียดและคำทำนายอยู่ในการ์ดภูมิทักษาด้านล่าง</div></div>`;
}
// ---- ภูมิทักษา: พื้นดวงและจร ----
function tkTransit(ch, age) {   // หน้า ๓๒๐: อายุย่างหาร ๘ เศษนับจากภูมิวันเกิด (เศษ ๐ = ภูมิที่ ๘ กาลกิณี)
  const s0 = TAKSA_ORDER.indexOf(ch.taksaLord), k = ((age - 1) % 8 + 8) % 8;
  const star = TAKSA_ORDER[(s0 + k) % 8], role = TAKSA_ROLE[k];
  return { age, k, star, role, grp: TAKSA_GRP[role], txt: TK_TR[String(star)] || "" };
}
const TK_GRP_CLS = { 1: "g", 0: "", "-1": "b" };
function tkCard(ch, nowIn) {
  if (!ch.born) return "";
  const now = nowIn || appNow(), lord = ch.taksaLord, map = ch.taksa;
  const ny = notYetCard(ch, now, "ภูมิทักษา", "ตำรา ภาค ๒ หน้า ๓๑๐–๓๒๔"); if (ny) return ny;
  const age = ageYang(ch.born, now), T = tkTransit(ch, age), N = tkTransit(ch, age + 1);
  const printed = lord <= 7 ? ch.dayIdx : null;   // ตำราพิมพ์คำทำนายพื้นทักษาไว้ ๗ วันเกิด
  const stars = TAKSA_ORDER.map((_, i) => TAKSA_ORDER[(TAKSA_ORDER.indexOf(lord) + i) % 8]);
  const nrow = (st, i) => { const role = TAKSA_ROLE[i], t = printed !== null ? TK_NAT[printed + "/" + st] : null;
    return `<tr><td>${esc(role)}${TK_ICON[role] || ""}</td><td>${esc(P[st].n)} (${TH(st)})</td><td class="${TK_GRP_CLS[TAKSA_GRP[role]]}">${esc(TAKSA_GRP_TH[TAKSA_GRP[role]])}</td><td>${esc(t || TK_DEF[role])}</td></tr>`; };
  const wheel = [...Array(8)].map((_, i) => tkTransit(ch, age + i));
  const tr = ch.synth || !ch.lunar || !ch.inTbl ? null : trYear(ch, age);
  const agree = tr === null ? "" : (T.grp > 0 && tr.lv > 0) || (T.grp < 0 && tr.lv < 0) || (T.grp === 0 && tr.lv === 0)
    ? `ทักษาจรไปทางเดียวกับปีจรของเลข ๗ ตัว (${esc(tr.word)}) จึงเป็นการย้ำผล`
    : `ทักษาจรกับปีจรของเลข ๗ ตัว (${esc(tr.word)}) ไปคนละทาง ตำราให้ยึดผลของเลข ๗ ตัวเป็นหลัก แล้วใช้ทักษาเป็นข้อสังเกตประกอบ`;
  return `<div class="card"><h2>ภูมิทักษา พื้นดวงและจร <span>ตำรา ภาค ๒ หน้า ๓๑๐–๓๒๑</span></h2>
<div class="kv"${hlA("tkL", hlPl(ch, lord, null, "ภูมิทักษา · ดาวประจำวันเกิด " + P[lord].n))}>• <b>ดาวประจำวันเกิด</b> ${esc(P[lord].n)} (${TH(lord)}) เป็นบริวาร${lord === 8 ? " — เกิดวันพุธกลางคืน ตำราให้ใช้ราหูเป็นเจ้าเรือนทักษา" : ""} · <b>ศรี</b> = เลข ${TH(stars[3])} · <b>กาลกิณี</b> = เลข ${TH(stars[7])}</div>
<div class="kv"${hlA("tkY", hlPl(ch, T.star, null, "ทักษาจรปีนี้ · ภูมิ" + T.role + " ดาว" + P[T.star].n))}>• <b>ทักษาจรปีนี้</b> อายุย่าง ${TH(age)} ปี ตกภูมิ<b>${esc(T.role)}</b> ดาว${esc(P[T.star].n)} <span class="pill ${TK_GRP_CLS[T.grp]}">${esc(TAKSA_GRP_TH[T.grp])}</span><br>
<span style="color:var(--tx2)">${esc(T.txt)}</span></div>
${agree ? `<div class="kv" style="color:var(--tx3);font-size:11.5px">${agree}</div>` : ""}
<div class="kv"${hlA("tkN", hlPl(ch, N.star, null, "ทักษาจรปีหน้า · ภูมิ" + N.role + " ดาว" + P[N.star].n))}>• <b>ปีหน้า</b> อายุย่าง ${TH(N.age)} ตกภูมิ${esc(N.role)} ดาว${esc(P[N.star].n)} (${esc(TAKSA_GRP_TH[N.grp])})</div>
<details><summary>พื้นทักษา ๘ ภูมิของคนเกิดวัน${esc(DAYS[ch.dayIdx])}</summary><div class="foot">
<div class="tbw"><table class="tb"><tr><th>ภูมิ</th><th>ดาว</th><th>ฝ่าย</th><th>${printed !== null ? "คำทำนายในตำรา" : "ความหมายภูมิ"}</th></tr>${stars.map(nrow).join("")}</table></div>
${printed === null ? "<br>ตำราพิมพ์คำทำนายพื้นทักษาไว้เฉพาะวันเกิดทั้งเจ็ด กรณีพุธกลางคืน (ราหูเป็นบริวาร) จึงแสดงเป็นความหมายของภูมิแทน" : ""}
</div></details>
<details><summary>ทักษาจร ๘ ปีข้างหน้า</summary><div class="foot">
<div class="tbw"><table class="tb"><tr><th>อายุย่าง</th>${wheel.map(w => `<th>${TH(w.age)}</th>`).join("")}</tr>
<tr><td>ภูมิ</td>${wheel.map(w => `<td class="${TK_GRP_CLS[w.grp]}">${esc(w.role)}</td>`).join("")}</tr>
<tr><td>ดาว</td>${wheel.map(w => `<td>${esc(P[w.star].n)}</td>`).join("")}</tr></table></div>
<br>ปีที่ตกกาลกิณีในช่วงนี้ = ${wheel.filter(w => w.grp < 0).map(w => "อายุย่าง " + TH(w.age)).join(" · ") || "ไม่มี"}
</div></details>
<details><summary>วิธีนับและที่มา</summary><div class="foot">
<b>พื้นทักษา</b> เลขประจำวันเกิดเป็นบริวาร แล้วเวียนขวาตามลำดับ ๑ → ๒ → ๓ → ๔ → ๗ → ๕ → ๘ → ๖ เป็น อายุ เดช ศรี มูละ อุตสาหะ มนตรี กาลกิณี (หน้า ๓๑๐–๓๑๑)<br>
<b>ทักษาจร</b> ใช้อายุย่าง เอา ๘ หาร เศษนับจากภูมิวันเกิดเป็นต้นไป ตกดาวใดพยากรณ์ตามดาวนั้น (หน้า ๓๒๐) · สองสำนวนที่ตำราเขียน (เดินทีละปี และหาร ๘) ให้ผลเดียวกัน แอปตรวจแล้วตรงกันทุกอายุ<br>
เศษ ๐ ตำราไม่ได้ระบุ แอปให้เป็นภูมิที่ ๘ (กาลกิณี) ตามการเดินทีละปี<br>
ระบบเลข ๗ ตัว<b>ไม่ลักเข้าตากลาง</b> ต่างจากทักษาในโหราศาสตร์ไทย (หน้า ๓๑๐ ๓๒๐)<br>
${esc(TK_SRC)}
</div></details></div>`;
}

// ================= v3.9.19 ฤกษ์ออกรถใหม่ (ภาค ๑ หน้า ๑๖๓ · เล่ม B หน้า ๑๖๘–๑๖๙) =================
// ภาค ๑: วันดี = วันที่เป็นศรีของวันเกิด · วันไม่ดี = วันกาลกิณีของวันเกิด (ทักษา) · นาวังดี+ธนัง+โภคาดี = รถหรู
//        นาวังเป็นบาปเคราะห์ (๑ ๓ ๗) ชนเสีย และฐานรองรับกลุ่มไม่ดี (๓ ๗ ๘ ๑๐ ๑๒ ๑๓ ๒๐) = ระวังอุบัติเหตุ แก้เคล็ดไม่ใส่ชื่อตนเอง
// เล่ม B: อายุ (พ.ศ. ลบกัน) นับวนในแถววันเกิด เลขที่ตกอ่านภพของเลขนั้นทั้ง ๓ แถว (ตัวอย่าง ๑๕ พ.ค. ๒๕๑๔ อายุ ๔๗ = เลข ๔ มาตา อริ ทาสี)
// ไม่ใช้ดิถีฤกษ์ไชยของเล่ม B (ผู้ใช้ขอตัดออก) · ไม่ใส่สีรถ (ตำราโยงไปภาคผนวกเรื่องสี)
const CAR_BADSUM = [3, 7, 8, 10, 12, 13, 20];
const CAR_DAY = s => (s === 8 ? "พุธกลางคืน (ราหู)" : DAYS[s - 1]);
function carOf(ch, nowIn) {
  if (!ch.born || !ch.taksa) return null;
  const now = nowIn || appNow(), map = ch.taksa;
  const roleStar = r => +Object.keys(map).find(k => map[k] === r);
  const sri = roleStar("ศรี"), kal = roleStar("กาลกิณี");
  const wd = sri === 8 ? 3 : sri - 1, next = [];
  for (let i = 1; next.length < 4 && i <= 35; i++) { const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i); if (d.getDay() === wd) next.push(d); }
  const at = (k, h) => ch.rows[k] ? ch.rows[k][HSX(ch)[k].indexOf(h)] : ch.B[k][(k === "b9" ? H9 : H8).indexOf(h)];
  const ev = (n, k) => { const cn = chonOf(n, ch.rows, ch.B, k), sup = supNatal(n, ch.rows); return { n, cn, sup, good: !cn.bad && !!sup && sup.grp === "good" }; };
  const nv = ev(at("b9", "นาวัง"), "b9"), tn = ev(at("day", "ธนัง"), "day"), pk = ev(at("day", "โภคา"), "day");
  const risk = [1, 3, 7].includes(nv.n) && nv.cn.bad && !!nv.sup && CAR_BADSUM.includes(nv.sup.sum);
  const lux = nv.good && tn.good && pk.good;
  const mrn = nv.n === at("year", "มรณะ");
  const bOf = age => { const col = ((age - 1) % 7 + 7) % 7, n = ch.rows.day[col], L = linksOf(n, ch.rows).slice(0, 3).map(x => x.h);
    return { age, col, n, L, bad: L.filter(h => BAD_HOUSE.includes(h)) }; };
  const ageB = now.getFullYear() - ch.born.getFullYear();
  return { sri, kal, next, nv, tn, pk, risk, lux, mrn, b: bOf(ageB), b1: bOf(ageB + 1) };
}
function carCard(ch, nowIn) {
  const c = carOf(ch, nowIn);
  if (!c) return "";
  const dS = d => `${DAYS[d.getDay()]} ${TH(d.getDate())} ${TH_MON_S[d.getMonth()]}`;
  const nvTxt = `นาวัง (ฐาน ๙) เป็นเลข ${TH(c.nv.n)} ${esc(P[c.nv.n].n)} · ${esc(chonTxt(c.nv.cn))} · ฐานรองรับ ${c.nv.sup ? TH(c.nv.sup.sum) : "–"}`;
  const verdict = c.risk
    ? `<span class="b">นาวังเป็นบาปเคราะห์ ชนเสีย และฐานรองรับอยู่กลุ่มไม่ดี</span> → ตำราว่าในชีวิตต้องระวังอุบัติเหตุเกี่ยวกับยานพาหนะและการเดินทาง · แก้เคล็ด: อย่าใส่ชื่อตนเองเป็นเจ้าของรถ ให้ใส่ชื่อคนอื่น เช่น สามี ภรรยา หรือญาติพี่น้อง`
    : c.lux ? `<span class="g">นาวัง ธนัง และโภคาดีทั้งสามภพ</span> → ตำราว่ามีเกณฑ์ได้เป็นเจ้าของรถหรูหรา ราคาแพง`
    : "ไม่เข้าเกณฑ์รถหรูและไม่เข้าเกณฑ์ระวังอุบัติเหตุของหน้านี้";
  const bLine = (x, lab) => `${lab} อายุ ${TH(x.age)} นับถึงช่องที่ ${TH(x.col + 1)} ของแถววันเกิด = เลข ${TH(x.n)} ตกภพ <b>${esc(x.L.join(" · "))}</b>${x.bad.length ? ` <span class="b">มีภพเสีย ${esc(x.bad.join(" "))}</span>` : ` <span class="g">ไม่มีภพเสีย</span>`}`;
  return `<div class="card"><h2>ฤกษ์ออกรถใหม่ <span>ตำรา ภาค ๑ หน้า ๑๖๓ · เล่ม B หน้า ๑๖๘–๑๖๙</span></h2>
<div class="kv">• <b>วันดี</b> วัน${esc(CAR_DAY(c.sri))} (ศรีของคนเกิดวัน${esc(DAYS[ch.dayIdx])}) <span class="pill g">⭐ ศรี</span><br>
<span style="color:var(--tx2)">ถัดไป: ${c.next.map(dS).join(" · ")}${c.sri === 8 ? " (ช่วงกลางคืน)" : ""}</span></div>
<div class="kv">• <b>วันที่ควรเลี่ยง</b> วัน${esc(CAR_DAY(c.kal))} (กาลกิณีของวันเกิด) <span class="pill b">🔥 กาลกิณี</span></div>
<div class="kv">• <b>ภพนาวังในดวง</b> ${verdict}<br><span style="color:var(--tx3);font-size:11.5px">${nvTxt}</span></div>
${c.mrn ? `<div class="kv" style="color:var(--tx3);font-size:11.5px">ดวงนี้เข้าเกณฑ์นาวังเป็นมรณะ (ภาค ๒ หน้า ๒๖๙) อีกข้อหนึ่งด้วย วิธีแก้ของเกณฑ์นั้นดูได้ที่แท็บดวงจร หัวข้อจรเจาะเรื่อง</div>` : ""}
<div class="kv">• <b>วิธีของเล่ม B</b> ${bLine(c.b, "ปีนี้")}<br><span style="color:var(--tx3);font-size:11.5px">${bLine(c.b1, "ปีหน้า")}</span></div>
<div class="kv" style="color:var(--tx3);font-size:11.5px">ตัวอย่างในเล่ม B ตกภพมาตา อริ ทาสี แล้วทำนายว่ารถที่ซื้อปีนั้นจะเกิดอุบัติเหตุแต่ไม่ถึงตาย ส่วนการเลือกเดือนและวันที่จะซื้อ ตำราอ่านเป็นรายดวงและไม่ได้ให้กฎตายตัว แอปจึงแสดงเฉพาะภพที่ตก</div>
<details><summary>วิธีนับและที่มา</summary><div class="foot">
<b>ภาค ๑ หน้า ๑๖๓</b> เอารถออกมาใช้ให้หาวันดี คือวันที่เป็นศรีของวันเกิด และเลี่ยงวันกาลกิณีของวันเกิด (ดูตารางทักษาด้านบน) · นาวังดีประกอบกับธนังและโภคาดี ได้รถหรูราคาแพง · นาวังเป็นเลขบาปพระเคราะห์ (๑ ๓ ๗) ชนเสีย (หินะ อริ มรณะ พยายะ มหาอุบาทว์) และฐานรองรับอยู่กลุ่มไม่ดี (๓ ๗ ๘ ๑๐ ๑๒ ๑๓ ๒๐) ต้องระวังอุบัติเหตุ · นาวังไม่ดีให้แก้เคล็ดโดยใส่ชื่อคนอื่นเป็นเจ้าของ<br>
แอปถือว่าภพ "ดี" เมื่อไม่ชนเสียและฐานรองรับอยู่กลุ่มดี<br>
<b>เล่ม B หน้า ๑๖๘–๑๖๙</b> ใช้อายุแบบเอา พ.ศ. ลบกัน นับวนในแถววันเกิดจนครบอายุ เลขที่ตกให้อ่านภพของเลขนั้นทั้งสามแถว ถ้าอยู่ตัวคนเดียวไม่มีสามีให้ใช้ดวงของตนเอง · ตัวอย่างเกิด ๑๕ พ.ค. ๒๕๑๔ วันเสาร์ ปี ๒๕๖๑ อายุ ๔๗ ได้เลข ๔ ตกมาตา อริ ทาสี และตำราให้ซื้อวันศุกร์ ซึ่งตรงกับวันศรีของคนเกิดวันเสาร์ในตารางทักษา<br>
สองวิธีนี้เป็นคนละระบบกัน ให้ใช้ประกอบกัน · เรื่องสีรถตำราโยงไปภาคผนวกเรื่องสี ซึ่งแอปไม่ได้ใส่ไว้
</div></details></div>`;
}
function carCheck() {
  const L = []; let ok = 0, fail = 0;
  const chk = (name, got, want) => { const pass = String(got) === String(want); if (pass) ok++; else { fail++; L.push(`✗ ${name}: ได้ ${got} ควรเป็น ${want}`); } };
  const ch = natalChart({ iso: "1971-05-15", time: null, name: "ตรวจรถ" }), c = carOf(ch, new Date(2018, 9, 1));
  chk("เล่ม B ตัวอย่าง ๑๕ พ.ค. ๒๕๑๔ อายุ", c.b.age, 47);
  chk("เล่ม B เลขที่ตก", c.b.n, 4);
  chk("เล่ม B ภพที่ตก", c.b.L.join(" "), "มาตา อริ ทาสี");
  chk("คนเกิดวันเสาร์ วันศรี = ศุกร์ (ตรงกับที่เล่ม B ให้ซื้อวันศุกร์)", CAR_DAY(c.sri), "ศุกร์");
  chk("วันศรีถัดไปทั้ง ๔ วันเป็นวันศุกร์", c.next.every(d => d.getDay() === 5) && c.next.length === 4, true);
  let risk = 0, lux = 0, both = 0, n = 0;
  for (let d = 0; d < 7; d++) for (let m = 1; m <= 12; m++) for (let y = 1; y <= 12; y++) { const x = chartOf(d + 1, m, y); n++;
    x.born = new Date(1990, 0, 1); x.taksaLord = d + 1; x.taksa = taksaOf(d + 1);
    const r = carOf(x, new Date(2026, 0, 1)); if (r.risk) risk++; if (r.lux) lux++; if (r.risk && r.lux) both++; }
  L.push(`ใน ${TH(n)} ผัง: เข้าเกณฑ์ระวังอุบัติเหตุ ${TH(risk)} · เกณฑ์รถหรู ${TH(lux)}`);
  chk("เกณฑ์ระวังอุบัติเหตุเกิดได้จริง", risk > 0, true);
  chk("เกณฑ์รถหรูเกิดได้จริง", lux > 0, true);
  chk("สองเกณฑ์ไม่ออกพร้อมกัน", both, 0);
  return { ok, fail, text: `ตรวจฤกษ์ออกรถ ${TH(ok + fail)} ข้อ · ตรง ${TH(ok)} · ไม่ตรง ${TH(fail)}\n\n${L.join("\n")}` };
}

// ================= ตรวจดวงจรกับตัวอย่างในตำรา ภาค ๒ (รอบ ๔) =================
const TR_GOLD = {
  // ดวงครู ๒๓ ก.ค. ๒๔๘๓ · ผังหน้า ๒๑๐ และคำอ่านหน้า ๒๑๑–๒๒๒
  teacher: { iso: "1940-07-23",
    year: [{ age: 63, house: "ทาสี", n: 4, pair: 3, sum: 13, heavy: ["หินะ"], ref: "หน้า ๒๑๐–๒๑๒ อายุ ๖๓ ตกทาสี เลข ๔ คู่ ๓ ฐานรองรับ ๑๓ ชนหินะ" }],
    month: [[1, "พันธุ", 4, 1, 11], [2, "ปุตตะ", 5, 7, 14], [3, "อริ", 6, 6, 10], [4, "ปัตนิ", 7, 5, 13], [5, "ตนุ", 1, 4, 9], [6, "กดุมภะ", 2, 3, 12], [7, "สหัชชะ", 3, 2, 15]],
    day: [[0, "หินะ", 4, 5, 12], [1, "ธนัง", 5, 1, 15], [2, "ปิตา", 6, 4, 11], [3, "มาตา", 7, 7, 14], [4, "โภคา", 1, 3, 10], [5, "มัชฌิมา", 2, 6, 13], [6, "อัตตะ", 3, 2, 9]],
    yam: [[4, 5, 12], [5, 1, 15], [6, 4, 11], [7, 7, 14], [1, 3, 10], [2, 6, 13], [3, 2, 9], [4, 5, 12]] },
  // หญิง ๘ พ.ย. ๒๕๑๕ · หน้า ๒๒๓–๒๒๖
  woman: { iso: "1972-11-08",
    year: [{ age: 31, house: "สหัชชะ", n: 7, pair: 4, sum: 16, heavy: ["มหาอุบาทว์"], ref: "หน้า ๒๒๓–๒๒๔ อายุ ๓๑ เลข ๗ คู่ ๔ ฐาน ๑๖ ชนมหาอุบาทว์ → ดี ๗๐–๗๕%" },
            { age: 32, house: "พันธุ", n: 1, pair: 3, sum: 12, heavy: ["อริ", "มรณะ"], ref: "หน้า ๒๒๕ อายุ ๓๒ เลข ๑ คู่ ๓ ฐาน ๑๒ ชนอริและมรณะสองต่อ มัชฌิมาไม่รับ" }] }
};
function trCheck() {
  const out = []; let ok = 0, fail = 0;
  const T = (pass, msg) => { pass ? ok++ : fail++; out.push(`${pass ? "✓" : "✗"} ${msg}`); };
  for (const key of ["teacher", "woman"]) {
    const G = TR_GOLD[key], ch = natalChart({ iso: G.iso, time: null, name: "ตรวจจร" });
    out.push(`\n— ${key === "teacher" ? "ดวงครู ๒๓ ก.ค. ๒๔๘๓" : "ตัวอย่างหญิง ๘ พ.ย. ๒๕๑๕"} —`);
    (G.year || []).forEach(g => {
      const t = trYear(ch, g.age);
      const pass = t.house === g.house && t.n === g.n && t.pair === g.pair && t.sum === g.sum && String([...t.chon.heavy].sort()) === String([...g.heavy].sort());
      T(pass, `ปีจรอายุ ${TH(g.age)}: ได้ภพ${t.house} เลข ${TH(t.n)} คู่ ${TH(t.pair)} ฐาน ${TH(t.sum)} ชน ${t.chon.heavy.join(" ") || "ไม่ชน"} — ${g.ref}`);
    });
    (G.month || []).forEach(([m, house, n, pair, sum]) => {
      const t = trMonth(ch, m), pass = t.house === house && t.n === n && t.pair === pair && t.sum === sum;
      T(pass, `เดือนจรเดือน ${TH(m)}: ภพ${t.house} เลข ${TH(t.n)} คู่ ${TH(t.pair)} ฐาน ${TH(t.sum)} (ตำราให้ ${house} ${TH(n)} คู่ ${TH(pair)} ฐาน ${TH(sum)})`);
      const t2 = trMonth(ch, m + 7);
      if (m <= 5) T(t2.col === t.col, `เดือน ${TH(m + 7)} ใช้ตำแหน่งเดียวกับเดือน ${TH(m)} (หน้า ๒๑๗)`);
    });
    (G.day || []).forEach(([d, house, n, pair, sum]) => {
      const t = trDay(ch, d), pass = t.house === house && t.n === n && t.pair === pair && t.sum === sum;
      T(pass, `วันจรวัน${DAYS[d]}: ภพ${t.house} เลข ${TH(t.n)} คู่ ${TH(t.pair)} ฐาน ${TH(t.sum)} (ตำราให้ ${house} ${TH(n)} คู่ ${TH(pair)} ฐาน ${TH(sum)})`);
    });
    if (G.yam) {
      const got = [...Array(8)].map((_, i) => { const t = trYam(ch, 0, i + 1); return [t.n, t.pair, t.sum]; });
      const same = got.every((g, i) => String(g) === String(G.yam[i]));
      T(same, `ยามจรวันอาทิตย์ ๘ ยาม: ${got.map(g => `${TH(g[0])}/${TH(g[1])}/${TH(g[2])}`).join(" ")} (ตารางหน้า ๒๒๒ · ยามที่ ๒ ตำราพิมพ์ฐาน ๑๔ แต่ผังให้ ๑๕ เป็นที่พิมพ์คลาด)`);
      T(String(got[0]) === String(got[7]), "ยามที่ ๘ กลับมาเหมือนยามแรก ตรงกับที่ตำราเขียน (หน้า ๒๒๒)");
    }
  }
  // กฎคุณภาพจรที่ตำราระบุเป็นเปอร์เซ็นต์
  const chW = natalChart({ iso: "1972-11-08", time: null, name: "ตรวจจร" });
  const a31 = trYear(chW, 31), a32 = trYear(chW, 32);
  T(a31.lv === 1 && a31.word === "ค่อนดี" && a31.score >= 65 && a31.score <= 80, `อายุ ๓๑ ฐาน ๑๖ ชนเสีย ได้ ${TH(a31.score)} ${a31.word} อยู่ย่าน ๗๐% ตามที่ตำราให้ (ดี ๗๐–๗๕% เสีย ๒๕–๓๐%) · v3.9.20 ระดับดี`);
  {   // v3.9.20 ลำดับวันร้าย หน้า ๒๒๗: อังคาร > พุธ > เสาร์ > ศุกร์ > อาทิตย์ · จันทร์ พฤหัสบดีดีที่สุด
    const sc = [2, 3, 6, 5, 0].map(d => trDay(chW, d).score), best = [1, 4].map(d => trDay(chW, d).score);
    T(sc.every((v, i) => i === 0 || v > sc[i - 1]) && best.every(v => v > sc[4]), `ลำดับวันร้ายหน้า ๒๒๗ อังคาร ${TH(sc[0])} < พุธ ${TH(sc[1])} < เสาร์ ${TH(sc[2])} < ศุกร์ ${TH(sc[3])} < อาทิตย์ ${TH(sc[4])} · จันทร์ ${TH(best[0])} พฤหัสบดี ${TH(best[1])} ดีที่สุด`);
    const ms = [[1, 8], [12, 5], [9, 2], [11, 4]].map(p => p.map(m => trMonth(chW, m).score));
    T(ms.every(p => p[0] === p[1]) && ms.every((p, i) => i === 0 || p[0] > ms[i - 1][0]), `ลำดับเดือนร้ายหน้า ๒๒๖ อ้าย/๘ ${TH(ms[0][0])} < ๑๒/๕ ${TH(ms[1][0])} < ๙/ยี่ ${TH(ms[2][0])} < ๑๑/๔ ${TH(ms[3][0])}`);
    const w = natalChart({ iso: "1972-11-08", time: null, sex: "f", name: "ตรวจจร" }), t31 = trYear(w, 31);
    T(t31.L1.some(x => x.k === "year" && x.h === "ทาสา"), `ดวงหญิงอายุ ๓๑ เลข ๗ ตกทาสา (เพศตรงข้าม) ตามหน้า ๒๒๔ · ได้ ${t31.L1.map(x => x.h).join(" ")}`);
  }
  T(a32.lv < 0 && !a32.notes.some(x => x.includes("ทอนทั้งดีและเสีย")), `อายุ ๓๒ ฐาน ๑๒ ชนสองต่อ ได้ ${TH(a32.score)} (${a32.word}) และมัชฌิมาไม่ทอน ตรงกฎหน้า ๒๒๕`);
  const chT = natalChart({ iso: "1940-07-23", time: null, name: "ตรวจจร" });
  const cases = [["วันจรวันอาทิตย์", trDay(chT, 0), ["หินะ", "มรณะ"], "หน้า ๒๑๙ ชนหินะ + มรณะ"],
                 ["วันจรวันอังคาร", trDay(chT, 2), ["หินะ", "อริ", "มหาอุบาทว์"], "หน้า ๒๒๐ ชนอริ + มหาอุบาทว์ + หินะ"],
                 ["เดือนจรเดือน ๓", trMonth(chT, 3), ["อริ", "มหาอุบาทว์"], "หน้า ๒๑๕ ชนเสียสองต่อ อริ + มหาอุบาทว์"],
                 ["เดือนจรเดือน ๖", trMonth(chT, 6), ["พยายะ"], "หน้า ๒๑๗ ชนพยายะ และมีมัชฌิมารับไว้ทำให้หนักเป็นเบา"]];
  cases.forEach(([lab, t, want, ref]) => {
    const got = [...t.chon.heavy].sort();
    T(String(got) === String([...want].sort()), `${lab}: ชนเสีย ${got.join(" ") || "ไม่ชน"} — ${ref}`);
  });
  T(trMonth(chT, 6).notes.some(x => x.includes("ทอนทั้งดีและเสีย")), "เดือน ๖ ของดวงครู มัชฌิมาทอนลง ๓๐% เพราะชนเสียต่อเดียว (หน้า ๒๑๗)");
  const T208 = Object.keys(TR_MIX).length;
  T(T208 === 9, `ตารางผลรวมปีจร × เดือนจร ครบ ${TH(T208)} ช่อง (หน้า ๒๐๘ ๒๑๕)`);
  // ครอบคลุม: ทุกอายุ ๑–๑๒๐ ทุกเดือน ทุกวัน ทุกยาม ของดวงจริง
  let n = 0, err = 0;
  for (const iso of ["1940-07-23", "1961-10-11", "1972-11-08"]) {
    const ch = natalChart({ iso, time: null, name: "ตรวจจร" });
    for (let a = 1; a <= 120; a++) { const t = trYear(ch, a); n++; if (!t.house || !t.sumTxt || t.score < 0 || t.score > 100) err++; }
    for (let m = 1; m <= 12; m++) { const t = trMonth(ch, m); n++; if (!t.house || !t.sumTxt) err++; }
    for (let d = 0; d < 7; d++) for (let y = 1; y <= 8; y++) { const t = trYam(ch, d, y); n++; if (!t.house || !t.sumTxt) err++; }
  }
  T(err === 0, `ครอบคลุม ${n.toLocaleString()} จุดจร (อายุ ๑–๑๒๐ · ๑๒ เดือน · ๗ วัน × ๘ ยาม ของ ๓ ดวง) ไม่มีค่าว่างหรือคะแนนนอกช่วง`);
  return { ok, fail, text: `ตรวจดวงจรกับตัวอย่างในตำรา ${TH(ok)}/${TH(ok + fail)} ข้อ\n${out.join("\n")}` };
}

// ================= ตรวจพื้นดวงตำรับโบราณ ยามเกิด และดิถีกำเนิด (รอบ ๓) =================
const PD_BASE = { gmb: [63, 24, 45], dist: [228, 744, 36], cross: [5, 41, 1, 1] };   // ค่าที่วัดได้ครั้งแรก ใช้กันการแก้ตารางโดยไม่รู้ตัว
function pdCheck() {
  const out = []; let ok = 0, fail = 0;
  const T = (pass, msg) => { pass ? ok++ : fail++; out.push(`${pass ? "✓" : "✗"} ${msg}`); };
  // ๑. ตารางครบและแยกค่าได้
  T(PD_DAY.length === 7 && PD_MON.length === 12 && PD_YR.length === 12 && LMON_TH.length === 12,
    `ตารางวัน ${TH(PD_DAY.length)} · เดือน ${TH(PD_MON.length)} · ปี ${TH(PD_YR.length)} ครบตามตำรา`);
  const cells = []; let blank = 0;
  PD_YM.forEach(r => { if (r.length !== 4) blank++; r.forEach(x => cells.push(pdCell(x))); });
  PD_YD.forEach(r => { if (r.length !== 7) blank++; r.forEach(x => cells.push(pdCell(x))); });
  const gmb = [cells.filter(c => c.g > 0).length, cells.filter(c => c.g === 0).length, cells.filter(c => c.g < 0).length];
  T(blank === 0 && cells.length === 132 && cells.every(c => c.t), `ปี × เดือน ๔๘ ช่อง + ปี × วัน ๘๔ ช่อง = ${TH(cells.length)} ช่อง มีคำทำนายครบทุกช่อง`);
  T(String(gmb) === String(PD_BASE.gmb), `ป้ายดี-กลาง-เสีย = ${gmb.map(TH).join(" · ")} (ครั้งแรกวัดได้ ${PD_BASE.gmb.map(TH).join(" · ")})`);
  // ๒. กฎคู่เดือน (หน้า ๗๘) และคู่ปี (หน้า ๘๐) ตรวจกับผังที่แอปสร้าง
  let pm = 0, py = 0;
  for (let m = 1; m <= 5; m++) if (chartOf(1, m, 1).rows.month[0] === chartOf(1, pdPair(m), 1).rows.month[0]) pm++;
  for (let y = 1; y <= 5; y++) if (chartOf(1, 1, y).rows.year[0] === chartOf(1, 1, pdPair(y)).rows.year[0]) py++;
  T(pm === 5, `คู่เดือน ๑–๘ ๒–๙ ๓–๑๐ ๔–๑๑ ๕–๑๒ ลงเลขเรือนตนุเท่ากัน ${TH(pm)}/๕ คู่ (ตำราหน้า ๗๘)`);
  const nopair = [6, 7].every(x => pdPair(x) === 0);
  T(nopair, `เดือน ๖ ๗ และปีมะเส็ง มะเมีย ไม่มีคู่ตามตำรา (ตำราจับคู่ไว้ ๕ คู่เท่านั้น) การ์ดแสดงข้อความแยกให้`);
  T(py === 5, `คู่ปี ชวด–มะแม ฉลู–วอก ขาล–ระกา เถาะ–จอ มะโรง–กุน ลงเลขเรือนมรณะเท่ากัน ${TH(py)}/๕ คู่ (ตำราหน้า ๘๐)`);
  // ๓. กฎสรุปหน้า ๘๗ ครอบ ๑,๐๐๘ แบบ
  const cnt = [0, 0, 0];
  for (let d = 1; d <= 7; d++) for (let m = 1; m <= 12; m++) for (let y = 1; y <= 12; y++) {
    const R = pdRead({ lunar: { month: m }, naksat: y, dayIdx: d - 1 });
    cnt[R.lv > 0 ? 0 : R.lv < 0 ? 2 : 1]++;
  }
  T(cnt[0] + cnt[1] + cnt[2] === 1008 && String(cnt) === String(PD_BASE.dist),
    `กฎสรุปหน้า ๘๗ ครอบ ๑,๐๐๘ แบบ: ดีมาก ${TH(cnt[0])} · ปานกลาง ${TH(cnt[1])} · เสียมาก ${TH(cnt[2])}`);
  // ๔. ยามเกิด ๑๑๒ ช่อง และช่วงเวลาต่อเนื่องครบวัน
  const yc = PD_YAM.flat(2);
  T(PD_YAM.length === 7 && yc.length === 112 && yc.every(t => t && t.length > 20), `คำทำนายยามเกิด ${TH(yc.length)} ช่อง (๗ วัน × ๒ ช่วง × ๘ ยาม) ไม่มีช่องว่าง`);
  let yok = 0;
  for (let h = 0; h < 24; h++) for (const mi of [1, 29, 30, 44, 59]) {
    const t = `${String(h).padStart(2, "0")}:${String(mi).padStart(2, "0")}`;
    const ch = natalChart({ iso: "2000-01-05", time: t, name: "ตรวจยาม" });
    const Y = yamRead(ch), want = ((h > 6 || (h === 6 && mi >= 1)) && h < 18) ? "กลางวัน" : "กลางคืน";
    if (Y && Y.text && Y.no >= 1 && Y.no <= 8 && Y.halfTxt === want) yok++;
  }
  T(yok === 120, `สุ่มเวลาเกิด ๑๒๐ เวลาในวันหนึ่ง ได้ยามและคำทำนายครบ ${TH(yok)}/๑๒๐`);
  const bd = yamRead(natalChart({ iso: "2000-01-05", time: "06:00" })), bn = yamRead(natalChart({ iso: "2000-01-05", time: "06:01" }));
  T(bd.halfTxt === "กลางคืน" && bd.no === 8 && bn.halfTxt === "กลางวัน" && bn.no === 1,
    `หัวต่อยาม: ๐๖:๐๐ = กลางคืนยาม ๘ · ๐๖:๐๑ = กลางวันยาม ๑ (ตารางหน้า ๘๘)`);
  // ๕. ดิถีกำเนิด ครอบทุกดิถี × เดือน × วัน และเทียบกับตารางฤกษ์ของแอป
  let dz = 0, derr = 0, maxh = 0;
  for (let d = 0; d < 7; d++) for (let m = 1; m <= 12; m++) for (let i = 1; i <= 30; i++) {
    const ph = i <= 15 ? "ขึ้น" : "แรม", kham = i <= 15 ? i : i - 15;
    try {
      const R = dithiRead({ lunar: { phase: ph, kham, month: m }, dayIdx: d });
      if (!R.tier || !R.sideTxt) derr++;
      if (!R.hits.length) dz++;
      maxh = Math.max(maxh, R.hits.length);
      R.hits.forEach(h => { if (!h.n || !h.t || !h.w) derr++; });
    } catch (e) { derr++; }
  }
  T(derr === 0, `ดิถีกำเนิดครอบ ๗ วัน × ๑๒ เดือน × ๓๐ ดิถี = ๒,๕๒๐ กรณี · error ${TH(derr)} · ไม่เข้าเกณฑ์ใดเลย ${TH(dz)} กรณี · เข้ามากสุด ${TH(maxh)} ข้อ`);
  const DGR = { "ดิถีพิฆาต": "พิฆาต", "วันทรธึก": "ทรทึก", "วันทักทิน": "กาลทัณฑ์", "วันอัคนีโรธ (โลกาวินาศ)": "โลกาวินาศ", "วันทินสูรย์": "ทินสูรย์", "วันกาลกิณี": "กาลกิณี" };
  let full = 0, cellOK = 0, part = 0, diff = 0;
  DG_DAY.forEach(o => {
    let c = 0;
    for (let w = 0; w < 7; w++) {
      const off = o.k[w] - 1, names = RERK7x30[w][off].split(", ");
      if (names.includes(DGR[o.n])) { c++; cellOK++; } else diff++;
    }
    if (c === 7) full++; else part++;
  });
  T(full === PD_BASE.cross[0] && cellOK === PD_BASE.cross[1] && part === PD_BASE.cross[2] && diff === PD_BASE.cross[3],
    `เทียบเกณฑ์ตามวันเกิดของตำรากับตารางฤกษ์ที่สกัดจากปฏิทิน: ตรงทั้ง ๗ วัน ${TH(full)} ชุด · รวม ${TH(cellOK)}/๔๒ ช่อง · ต่างกัน ${TH(diff)} ช่อง (วันอัคนีโรธ วันพุธ ตำรา ๓ ค่ำ ปฏิทิน ๙ ค่ำ)`);
  return { ok, fail, text: `ตรวจพื้นดวงตำรับโบราณ ${TH(ok)}/${TH(ok + fail)} ข้อ\n\n${out.join("\n")}` };
}

// v2.1.2 การ์ดทั้งหมดของหน้าผัง แยกออกมาให้หน้าเกี่ยวกับดึง "ที่มา" ของดวงเดียวกันได้
// ================= v2.2.0 ผังย่อติดหัวจอ (แบบ A ที่ผู้ใช้เลือก) =================
// แท็บ ๒–๔ มีผังเลขย่ออยู่ใต้แถบแท็บเสมอ · แตะเรื่อง กฎ เกณฑ์ หรือดวงจรรายการไหน ผังไฮไลต์ภพ ดาว และดาวชิ่งของรายการนั้น
// ใช้สีชุดเดียวกับตอนแตะเลขในผังเต็ม: f ภพหลัก = พื้นสีดาวเต็ม · p เลขเดียวกันและภพเสริม = พื้นอ่อนมีกรอบ
// b เลขคู่ (ชิ่ง) = วงกลม · pc ช่องชิ่งตรงตัวในฐาน ๕–๗ = วงกลมพื้นเข้ม · s ฐานรองรับ = กรอบทอง
let HLREG = null;   // ตัวเก็บไฮไลต์ระหว่างสร้างการ์ดของหน้าผัง (natalCards เปิด-ปิด) · หน้าอื่นเป็น null จึงไม่ติด data-hl
const hlUniq = A => [...new Set((A || []).filter(Boolean))];
const colOfH = (k, h, o) => (k === "b8" ? H8 : k === "b9" ? H9 : HSX(o)[k]).indexOf(h);
const cidH = (k, h, o) => { const c = colOfH(k, h, o); return c < 0 ? null : cid(k, c); };
const HL_KEYS = ["f", "p", "b", "pc", "s"];
function hlJoin(...L) {
  const o = { f: [], p: [], b: [], pc: [], s: [] };
  L.filter(Boolean).forEach(x => HL_KEYS.forEach(k => { o[k] = o[k].concat(x[k] || []); }));
  HL_KEYS.forEach(k => { o[k] = hlUniq(o[k]); });
  o.p = o.p.filter(x => !o.f.includes(x));
  return o;
}
// ภพหลักหนึ่งช่อง = เหมือนแตะเลขในผังเต็ม: เลขเดียวกันทุกที่ + เลขคู่ (ชิ่ง) + ฐานรองรับ
function hlCell(ch, k, c, ching) {
  if (c == null || c < 0) return null;
  const R = ch.rows, B = ch.B, n = (is89(k) ? B[k] : R[k])[c];
  if (n == null) return null;
  const sup = supNatal(n, R), o = { f: [cid(k, c)], p: lid(linksOf(n, R, B)), b: [], pc: [], s: sup ? [cid("sum", sup.col)] : [] };
  if (ching !== false && CHING_PAIR[k]) { const hk = CHING_PAIR[k], m = B[hk][c]; o.pc = [cid(hk, c)]; if (m !== n) o.b = lid(linksOf(m, R, B)); }
  return o;
}
// ดาวหนึ่งดวง = ทุกช่องที่เป็นเลขนั้น + ฐานรองรับ · cls "b" ใช้วงกลมแทนกรอบ (ดาวแทรก) · ราหู ๘ ไม่มีในผังเลข ๗ ตัว
function hlNum(ch, n, cls) {
  if (!(n >= 1 && n <= 7)) return null;
  const sup = supNatal(n, ch.rows), L = lid(linksOf(n, ch.rows, ch.B));
  return { f: [], p: cls === "b" ? [] : L, b: cls === "b" ? L : [], pc: [], s: sup ? [cid("sum", sup.col)] : [] };
}
const hlPlTxt = n => (n >= 1 && n <= 7 ? `${TH(n)} ${esc(P[n].n)}` : `${TH(n)} ${esc((P[n] || {}).n || "")} (ไม่มีในผังเลข ๗ ตัว)`);
function hlPl(ch, a, b, title) {
  const two = b != null && b !== a, o = hlJoin(hlNum(ch, a), two ? hlNum(ch, b, "b") : null);
  return { ...o, t: `<b>${esc(title)}</b> · ${two ? `กรอบ = ดาว ${hlPlTxt(a)} · วง = ดาว ${hlPlTxt(b)}` : `ดาว ${hlPlTxt(a)} ทุกช่องที่ตั้ง`}` };
}
// ---- ๒๘ เรื่อง (ภพหลักและภพเสริมจาก NTOPICS) ----
function hlTopic(ch, s) {
  const tp = s.tp, nA = (k, h) => numAtH(ch, k, h);
  let o = null, t = "";
  if (tp.cells) {
    o = hlJoin(...tp.cells.map(([k, h]) => hlCell(ch, k, colOfH(k, h, ch))), { p: tpSup(tp, ch).map(([k, h]) => cidH(k, h, ch)) });
    const pr = tp.cells.filter(([k]) => CHING_PAIR[k]).map(([k, h]) => { const c = colOfH(k, h, ch), m = ch.B[CHING_PAIR[k]][c];
      return m === ch.rows[k][c] ? `${esc(h)} คู่กับตัวเอง` : `คู่ ${TH(m)}`; });
    t = `ภพหลัก ${tp.cells.map(([k, h]) => `${esc(h)} ${TH(nA(k, h))}`).join(" · ")}${tpSup(tp, ch).length ? ` · เสริม ${tpSup(tp, ch).map(([k, h]) => `${esc(h)} ${TH(nA(k, h))}`).join(" · ")}` : ""}${pr.length ? " · " + pr.join(" · ") : ""}`;
  } else if (tp.pls) {
    o = hlJoin(...tp.pls.map(([n]) => hlNum(ch, n)));
    t = `ดาว ${tp.pls.map(([n]) => hlPlTxt(n)).join(" · ")} ทุกช่องที่ตั้ง`;
  } else if (tp.pl) {
    o = hlJoin(hlNum(ch, tp.pl)); t = `ดาว ${hlPlTxt(tp.pl)} ทุกช่องที่ตั้ง`;
  } else if (tp.seer) {
    const hs = seer6(ch);
    o = hlJoin(...hs.map(x => hlSeer(ch, x.c.i, true)));
    t = hs.length ? `เกณฑ์ดวงหมอดูที่เข้า ข้อ ${hs.map(x => TH(x.c.i)).join(" ")}` : "ไม่มีเกณฑ์ดวงหมอดูข้อใดเข้า";
  }
  return o ? { ...o, t: `<b>${tp.ic} ${esc(tp.k)}</b> · ${t}` } : null;
}
// ---- เกณฑ์ดวงชะตาหมอดู ๖ ข้อ: ข้อที่เข้า = ช่องที่ทำให้เข้า · ข้อที่ไม่เข้า = ภพที่ตำราให้ดู (กรอบ) ----
