const s6PsStar = (r1, r2, r3) => s6m7(r1[3] + r2[3] + r3[3]);
function s6Ps(ch) {
  if (ch.synth || !ch.astro) return null;
  const G = s6G(ch), r1 = G.R.day, r2 = G.R.month, r3 = G.R.year, star = s6PsStar(r1, r2, r3);
  return { G, x: G.x, be: G.be, m: G.m, r1, r2, r3, sum: r1[3] + r2[3] + r3[3], star, at: G.where(star) };
}
// ข้อตัดสิน 51 + 93: เสาสิเนรุกำเนิด · ยามใหญ่และยามย่อยตามตารางยามอัฐกาล น.๗๔–๗๖ · ยามย่อย = ยามใหญ่แบ่ง ๘ ช่วงละ ๖๗๕ วินาที
// ดาวยามย่อยเริ่มที่ดาวยามใหญ่ แล้วบวก ๕ (กลางวัน) / ๔ (กลางคืน) · ตรงตัวอย่าง น.๗๙ (S6-SN-002) ๑๙๙ (CH-004) ๒๐๔ (YU-005)
function s6SnCalc(dayNum, mm, up, kham) {
  const isDay = mm > 360 && mm <= 1080, off = isDay ? mm - 361 : (mm >= 1081 ? mm - 1081 : mm + 359);
  const i = clamp(Math.floor(off / 90), 0, 7), j = clamp(Math.ceil((off - 90 * i + 1) * 60 / 675) - 1, 0, 7), st = isDay ? 5 : 4;
  const big = s6m7(dayNum + st * i), small = s6m7(big + st * j), B = s6Bhumi(!isDay, up, kham), col = [];
  for (let n = 0, k = B.ring.indexOf(small); n < 8; n++, k = s6r8(k + B.dir)) col.push(B.ring[k]);
  return { night: !isDay, i, j, big, small, B, col };
}
// ข้อตัดสิน 93: ยามใหญ่/ยามย่อยตามตารางยามอัฐกาล น.๗๔–๗๖ · กลางวัน ๐๖.๐๐.๐๑–๑๘.๐๐.๐๐ · ยามใหญ่ ๙๐ นาที · ยามย่อย ๑๑ นาที ๑๕ วินาที
function s6Yam(ch) {
  if (!ch.hasTime || !ch.born) return null;
  const S = s6SnCalc(ch.dayNum, ch.born.getHours() * 60 + ch.born.getMinutes(), true, 1);
  return { i: S.i, no: S.i + 1, j: S.j, half: S.night ? 1 : 0, halfTxt: S.night ? "กลางคืน" : "กลางวัน", big: S.big, small: S.small };
}
function s6Sn(ch) {
  if (ch.synth || !ch.hasTime || !ch.born || !ch.lunar) return null;
  return s6SnCalc(ch.dayNum, ch.born.getHours() * 60 + ch.born.getMinutes(), ch.lunar.phase === "ขึ้น", ch.lunar.kham);
}
const s6Hd = t => `<h2>${t} <span>ตำรารอง · ไม่คิดคะแนน</span></h2>`;
