const mpAttr = (at, n) => { const m = new RegExp("\\s" + n + "=\"([^\"]*)\"").exec(at); return m ? m[1] : null; };
// หาแท็กปิดคู่ของแท็กเปิดที่ตำแหน่ง i (นับซ้อน) · คืนตำแหน่งหลังแท็กปิด หรือ -1
function mpClose(h, i, tag) {
  const re = new RegExp("<" + tag + "[\\s>]|</" + tag + ">", "g"); re.lastIndex = i; let d = 0, m;
  while ((m = re.exec(h))) { if (m[0][1] === "/") { if (--d === 0) return m.index + m[0].length; } else d++; }
  return -1;
}
// แถว/ชิป ที่มี data-hl (กฎ เกณฑ์ ดาว) → ลิงก์ไปหน้าผังที่ไฮไลต์รายการนั้น
function mpHLLinks(h, HL) {
  if (!HL) return h;
  let out = "", i = 0; const re = /<(div|span)\b([^>]*\sdata-hl="([^"]+)"[^>]*)>/g; let m;
  while ((m = re.exec(h))) {
    const [all, tag, at, k] = m, j = m.index, e = mpClose(h, j, tag);
    if (e < 0 || !(HL[k] || MP_TRM[k])) continue;
    const el = h.slice(j, e), inner = el.slice(all.length, -(tag.length + 3)), href = `satta7://hl?k=${encodeURIComponent(k)}`;
    if (tag === "span") { if (/<a\b/.test(inner)) continue; out += h.slice(i, j) + `<a${at} href="${href}">${inner}</a>`; }
    else out += h.slice(i, j) + `<${tag}${at}>${inner}<a class="hlgo" href="${href}">🔍 ดูบนผัง ›</a></${tag}>`;
    i = e; re.lastIndex = e;
  }
  return out + h.slice(i);
}
// แตก <details> ชั้นบนสุดของ html · ชั้นในทำต่อในหน้าย่อย
function mpExplode(html, pk, tab, nodes, HL, rt) {
  rt = rt || "p";
  let out = "", i = 0, n = 0;
  for (;;) {
    const j = html.indexOf("<details", i);
    if (j < 0) { out += mpHLLinks(html.slice(i), HL); break; }
    const e = mpClose(html, j, "details"); if (e < 0) { out += mpHLLinks(html.slice(i), HL); break; }
    out += mpHLLinks(html.slice(i, j), HL);
    const blk = html.slice(j, e), om = /^<details\b([^>]*)>\s*<summary\b[^>]*>([\s\S]*?)<\/summary>/.exec(blk);
    if (!om) { out += blk; i = e; continue; }
    const at = om[1], cls = mpAttr(at, "class") || "", hl = mpAttr(at, "data-hl"), sum = om[2], body = blk.slice(om[0].length, -"</details>".length);
    const txt = body.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim().length;
    const op = /\sopen\b/.test(at.replace(/"[^"]*"/g, "")), idA = mpAttr(at, "id");
    if (op || (!hl && txt <= MP_INLINE && body.indexOf("<details") < 0)) {
      const inner = body.indexOf("<details") < 0 ? mpHLLinks(body, HL) : mpExplode(body, `${pk}-${n++}`, tab, nodes, HL, rt);
      out += `<div class="s7d${cls ? " " + cls : ""} s7o"${idA ? ` id="${idA}"` : ""}><div class="s7s">${sum}</div><div class="s7b">${inner}</div></div>`;
    } else {
      const id = `${pk}-${n++}`;
      nodes[id] = { id, tab, parent: pk, cls, hl, sum, html: "" };
      nodes[id].html = mpExplode(body, id, tab, nodes, HL, rt);
      out += `<a class="s7d nrow${cls ? " " + cls : ""}"${idA ? ` id="${idA}"` : ""} href="satta7://${rt}?k=${id}"><span class="s7s">${sum}</span></a>`;
    }
    i = e;
  }
  return out;
}
function mpBuild(ch, at, so) {   // v3.9.37 at = เวลาจำลอง (ไม่ใส่ = เวลาจริง) · v3.9.41 so = { m, msg } โหมดผังจำลอง (มีแถบ 🧪)
  return withSim(at, () => ({ ...mpBuild0(ch), at: at || null, sim: at && so ? { at, m: SIM_MODES.includes(so.m) ? so.m : "year", msg: so.msg || "", q: so.q || "" } : null }));
}
function mpBuild0(ch) {
  const { SECS, T, HL } = natalCards(ch);
  SECS.forEach(x => { x.cards = x.cards.map((c, i) => { const r = srcSplit(c); if (!r.src.length) return c;
    const link = `<a class="srcl" href="satta7://about?a=src-${x.id}-${i}">📚 ที่มาและวิธีคิด ›</a>`;
    return /<\/div>\s*$/.test(r.html) ? r.html.replace(/<\/div>\s*$/, link + "</div>") : r.html + link; }); });
  const nodes = {}, tabs = {};
  const chartH = mpExplode(SECS[0].cards.shift(), "s1c", "s1", nodes, {});
  SECS.forEach(x => { tabs[x.id] = { id: x.id, ic: x.ic, nav: x.nav, n: x.n, h: x.h, html: mpExplode(x.cards.join(""), x.id, x.id, nodes, HL) }; });
  const tpNode = {}; Object.keys(nodes).forEach(k => { const h = nodes[k].hl; if (h && /^tp\d+$/.test(h) && !tpNode[h]) tpNode[h] = k; });
  const tpLink = h => h.replace(/satta7:\/\/tp\?k=(tp\d+)/g, (m, k) => tpNode[k] ? `satta7://p?k=${tpNode[k]}` : `satta7://hl?k=${k}`);
  Object.keys(tabs).forEach(k => { tabs[k].html = tpLink(tabs[k].html); }); Object.keys(nodes).forEach(k => { nodes[k].html = tpLink(nodes[k].html); });
  return { ch, T, HL, D: JSON.parse(chartPanes(ch, T)), chartH, tabs, order: SECS.map(x => x.id), nodes };
}
// ผังแบบไม่มีสคริปต์ · o = { r: ไฮไลต์ (รายการจาก D ใช้ id เต็ม หรือจาก HL ใช้ id ไม่มี c-), pre, cell, mode, cap, pane }
function mpChart(M, o) {
  o = o || {}; let h = M.chartH; const cls = {}, r = o.r, pre = o.pre || "";
  const add = (L, c) => (Array.isArray(L) ? L : L ? [L] : []).forEach(x => { const id = pre + x; (cls[id] = cls[id] || []).push(c); });
  if (r) { add(r.p, "rp"); add(r.b, "rb"); add(r.pc, "rpc"); add(r.s, "rs"); add(r.f, "rpf"); }
  if (o.cell) add(o.cell, "rpf");
  const any = Object.keys(cls).length > 0;
  h = h.replace(/<div class="cell([^"]*)" id="(c-[^"]+)">([\s\S]*?)<\/div>/g, (m, c, id, inner) =>
    `<a class="cell${c}${cls[id] ? " " + [...new Set(cls[id])].join(" ") : ""}" id="${id}" href="${o.cell === id ? "satta7://up" : `satta7://cell?k=${id}`}">${inner}</a>`);
  if (any) h = h.replace('<div class="grid" id="g"', '<div class="grid tap" id="g"');
  h = h.replace(/<a( class="on")? data-m="([a-z]+)">/g, (m, on, k) => `<a${k === (o.mode || "natal") ? ' class="on"' : ""} data-m="${k}" href="satta7://cmode?m=${k}">`);
  if (o.cap) h = h.replace('<div class="hcap" id="hcap"></div>', `<div class="hcap" id="hcap" style="display:block">${o.cap}</div>`);
  if (o.pane) h = h.replace('<div class="pane" id="pane" style="display:none"></div>', `<div class="pane" id="pane">${o.pane}</div>`);
  h = h.replace(/<div class="mode" id="mode">[\s\S]*?<\/div>/, o.modeBar || "");   // v3.9.3 ไม่มีแถบโหมดซ้อนบนผัง
  return h;
}
const MP_CHT = { s1: 1, s2: 1, s3: 1 };
const MP_INFO = `<div class="kv foot mpinfo"><b>ⓘ</b> ช่องที่สว่างคือภพของเรื่องนี้ · แตะช่องเลขเพื่ออ่านเลขนั้น</div>`;
