  T(G.filter(x => x.house || (x.planet && x.planet < 8)).every(x => glossMine(c, x).length), "ภพและดาว ๑–๗ มีชั้น ในดวงคุณ");
  const f = glossFind(`เลข ๓ ชนเสีย (มรณะ) · มหาอุปถัมภ์ · ${TERM_STD["ศุภะ"][0]} · วันพฤหัสบดี`).map(x => x.t);
  T(f.join(" ") === "ชนเสีย มรณะ มหาอุปถัมภ์ ศุภะ พฤหัสบดี", `จับศัพท์ในข้อความ: คำแปรผันชี้คำมาตรฐาน · คำยาวก่อนคำสั้น (${f.join(" ")})`);
  const M = mpBuild(c), ks = Object.keys(M.nodes), withG = ks.filter(k => /class="card gls"/.test(mpRender(M, { r: "p", k, y: 0 }, M.nodes[k].tab)));
