// ================= รอบ 67 (UX_PLAN ข้อ 5b): ประโยคกลไก =================
// บรรทัดเดียวใต้คะแนนของหน้าเรื่อง: เลขอะไร อยู่ภพไหน ฐานรองรับ ชนอะไร → จึงได้ผลนี้ · ใช้ค่าที่ topicScore คิดไว้แล้ว ไม่คิดสูตรใหม่
const MECH_GRP = { good: "ดี", mid: "กลาง", bad: "ไม่ดี" };
const mechChon = cn => (cn.bad ? `ชนเสีย ${cn.heavy.join(" ")}` : cn.light.length ? `ชนภพ ${cn.light.join(" ")}` : "ไม่ชนเสีย");
const mechCell = c => `${c.h}${is89(c.k) ? ` ${B89TH[c.k]}` : ""} เลข ${TH(c.n)} (${P[c.n].n}) · ${c.sc.sup ? `ฐานรองรับ ${TH(c.sc.sum)} ${MECH_GRP[c.sc.grp]}` : "ไม่มีฐานรองรับ"} · ${mechChon(c.sc.cn)}${c.inv ? " · ภพเสีย อ่านกลับด้าน" : ""}`;
function mechParts(s) {
  const a = [];
  if (s.seerV) a.push(`เข้าเกณฑ์ดวงหมอดู ${TH(s.parts.filter(p => /^เกณฑ์ข้อ/.test(p.why)).length)} จาก ๖ ข้อ`);
  else if (s.cells.some(c => c.k === "planet")) s.cells.forEach(c => a.push(`ดาว${P[c.n].n} (${TH(c.n)}) ตั้งอยู่ ${c.items.map(x => x.h).join(" ")} · กำลังรวม ${TH(Math.round(c.ben))}`));
  else { s.cells.filter(c => !c.sup).forEach(c => a.push(mechCell(c))); const n = s.cells.filter(c => c.sup).length; if (n) a.push(`เรือนประกอบ ${TH(n)} เรือน`); }
  const rd = s.rules.reduce((t, x) => t + (x.d || 0), 0), nr = s.rules.filter(x => x.d).length;
  if (nr) a.push(`กฎเฉพาะ ${TH(nr)} ข้อ (${sgn(rd)})`);
  if (!s.seerV) { const od = s.parts.filter(p => p.d && !/^กฎ:/.test(p.why)).reduce((t, p) => t + p.d, 0); if (od) a.push(`ปรับตามตำรา ${sgn(od)}`); }
  return a;
}
function mechLine(ch, s) {
  const a = mechParts(s); if (!a.length) return "";
  return `<div class="mech" style="font-size:13px;line-height:1.6;margin:6px 0 2px;color:var(--sub)"><b>⚙︎ กลไก</b> ${a.map(esc).join(" <span class=\"mj\">+</span> ")} <span class="mj">→</span> <b>${mkW(s.word)} ${TH(s.score)}</b></div>`;
}
function mechCheck() {
  const L = []; let ok = 0, fail = 0; const T = (c, m) => { if (c) ok++; else fail++; L.push(`${c ? "✓" : "✗"} ${m}`); };
  const P8 = [["1992-12-12", "10:50", "f"], ["1972-11-08", "", "f"], ["1940-07-23", "05:30", "m"], ["1964-08-04", "14:00", "m"]];
  let n = 0, bad = [], chonOK = true, numOK = true;
  P8.forEach(([iso, time, sex]) => { const ch = natalChart({ iso, time, name: "x", sex }); if (ch.err) return;
    NTOPICS.forEach(tp => { const s = topicScore(ch, tp, []), h = mechLine(ch, s); n++;
      if (!h || /undefined|NaN/.test(h) || h.indexOf(`${mkW(s.word)} ${TH(s.score)}</b>`) < 0) bad.push(tp.k);
      s.cells.filter(c => !c.sup && c.k !== "planet").forEach(c => { if (h.indexOf(`${c.h}${is89(c.k) ? ` ${B89TH[c.k]}` : ""} เลข ${TH(c.n)}`) < 0) numOK = false;
        if (c.sc.cn.bad !== mechCell(c).includes("· ชนเสีย ") || h.indexOf(esc(mechCell(c))) < 0) chonOK = false; }); }); });
  T(!bad.length, `ทุกเรื่องมีประโยคกลไก และลงท้ายด้วยคำผลและคะแนนเดียวกับหัวการ์ด (${TH(n)} เรื่อง${bad.length ? " · พลาด " + bad.slice(0, 3).join(" ") : ""})`);
  T(numOK, "ภพหลักทุกภพบอกเลขที่ตกในภพนั้น");
  T(chonOK, "บอก ชนเสีย ตรงกับผล chonOf ของเลขนั้นทุกภพ");
  const ch = natalChart({ iso: "1992-12-12", time: "10:50", name: "x", sex: "f" }), M = mpBuild(ch), ks = Object.keys(M.nodes);
  const pg = ks.map(k => mpRender(M, { r: "p", k, y: 0 }, M.nodes[k].tab)), wm = pg.filter(h => /class="mech"/.test(h));
  T(wm.length >= NTOPICS.length, `หน้าเรื่องย่อยที่มีประโยคกลไก ${TH(wm.length)} หน้า (อย่างน้อยเท่าจำนวนเรื่อง ${TH(NTOPICS.length)})`);
  const ws = wm.filter(h => /class="mech"[^>]*>[^\n]*ฐานรองรับ/.test(h));
  const mc = h => (/<div class="mech"[\s\S]*?<\/div>/.exec(h) || [""])[0];
  T(ws.length && ws.every(h => /satta7:\/\/term\?k=sup"/.test(h) && (!mc(h).includes("· ชนเสีย ") || /satta7:\/\/term\?k=chon"/.test(h))), `หน้าที่ประโยคกลไกอ้างฐานรองรับ (${TH(ws.length)} หน้า) มีลิงก์ศัพท์ ฐานรองรับ · ที่บอกชนเสียมีลิงก์ ชนเสีย`);
  return `ผ่าน ${TH(ok)} · ไม่ผ่าน ${TH(fail)}\n` + L.join("\n");
}

// ================= รอบ 68 (UX_PLAN ข้อ 5c · ข้อตัดสิน 71–72): สัญลักษณ์ระดับผล =================
// คงสีเดิม · เติมสัญลักษณ์หน้าคำผล ๕ ระดับ ▲▲ ดี · ▲ ค่อนดี · ◐ กลาง · ▼ ค่อนร้าย · ▼▼ ร้าย · ◇ เฉย (ระดับดาว)
// ใช้กับป้าย (คะแนน ชิป ป้ายดาว กล่องคำตอบ ช่องสรุป) เท่านั้น ไม่แตะประโยคในเนื้อความ · คำระดับเรือนเสีย (BADV) ไม่ใส่สัญลักษณ์
function mkCheck() {
  const L = []; let ok = 0, fail = 0; const T = (c, m) => { if (c) ok++; else fail++; L.push(`${c ? "✓" : "✗"} ${m}`); };
  T([2, 1, 0, -1, -2].map(v => LV_MK[VW5[v]]).join(" ") === "▲ △ ◐ ▽ ▼", "คำผล ๕ ระดับ (VW5) ได้ ▲ △ ◐ ▽ ▼ ตามข้อตัดสิน 74 (แทน 72)");
  T(Object.values(STAR_LAB).every(w => LV_MK[w]) && LV_MK[STAR_LAB.idle] === "◇", "ระดับดาวทุกระดับมีสัญลักษณ์ · เฉย = ◇");
  T(["ร้ายชัด", "ร้ายค่อนชัด", "ร้ายพอประมาณ", "ร้ายเบาลง", "แทบไม่สำแดง"].every(w => !LV_MK[w]), "คำระดับเรือนเสีย (BADV) ไม่ใส่สัญลักษณ์ (คนละมาตรา)");
  const c = natalChart({ iso: "1992-12-12", time: "10:50", name: "x", sex: "f" }), M = mpBuild(c);
  const pills = [], bad = [];   // ป้ายสถิติการกระจาย (สูง กลาง ต่ำ %) ไม่ใช่คำผล ข้ามไป
  const scan = h => (h.match(/<span class="pill[^"]*">[\s\S]*?<\/span>/g) || []).forEach(p => pills.push(p));
  M.order.forEach(id => scan(mpRender(M, { r: "tab", k: id, y: 0 }, id)));
  Object.keys(M.nodes).forEach(k => scan(mpRender(M, { r: "p", k, y: 0 }, M.nodes[k].tab)));
  pills.forEach(p => { const t = p.replace(/<[^>]+>/g, " "); if (/%/.test(t)) return; Object.keys(LV_MK).forEach(w => { if (new RegExp(`(^|[\\s๐-๙])${w}(\\s|$)`).test(t) && !t.includes(LV_MK[w] + " ")) bad.push(t.trim()); }); });
  T(!bad.length, `ป้ายที่มีคำผลมีสัญลักษณ์ครบ (${TH(pills.length)} ป้าย${bad.length ? " · ขาด " + bad.slice(0, 3).join(" | ") : ""})`);
  const s0 = topicScore(c, NTOPICS[0], []);
  T(mechLine(c, s0).includes(`${mkW(s0.word)} ${TH(s0.score)}</b>`), "บรรทัดกลไกลงท้ายด้วยสัญลักษณ์ + คำผล + คะแนน");
  T(glossAll().some(x => x.id === "lvm") && glossFind("▲ ดี").some(x => x.id === "lvm"), "มีศัพท์ ระดับผล ให้แตะดูความหมายของสัญลักษณ์");
  return `ผ่าน ${TH(ok)} · ไม่ผ่าน ${TH(fail)}\n` + L.join("\n");
}

