  const P = [["1992-12-12", "10:50", "f"], ["1972-11-08", "", "f"], ["1940-07-23", "05:30", "m"], ["1961-10-11", "23:15", ""], ["1964-08-04", "14:00", "m"], ["1959-04-14", "", "f"], ["1990-01-15", "06:00", "m"], ["2001-02-28", "18:40", "f"]];
